export const HIV_V2=[
q("hiv-adv-001",["Transmiterea infecției HIV:",
 ["riscul după înțepătura cu ac contaminat este 3%","are ca marker principal viremia, maximă în infecția acută","circumcizia nu reduce riscul bărbatului circumcis","pare mai importantă de la femeie la bărbat","verticală, fără intervenție, este 15% în Europa"],"BE",1426,"HIV — Epidemiologie și patogenie: Căile de transmitere a HIV",
 "Cuantificarea corectă a riscului de transmitere HIV pe diferite căi și recunoașterea factorilor care îl modulează (viremie, direcție a transmiterii, circumcizie).",
 ["Nu: riscul după o singură înțepătură cu ac contaminat cu sânge HIV-pozitiv este de aproximativ 0,3%.","Încărcătura virală este cel mai important marker al riscului de transmitere și are nivelul maxim în infecția acută.","Nu: circumcizia reduce atât dobândirea, cât și transmiterea HIV.","Nu: transmiterea pare mai importantă de la bărbat la femeie și către partenerul receptiv în relațiile anale.","Fără intervenție, studiile europene indică o transmitere verticală de 15%, cu rate de până la 40% în Africa și SUA."]],
 [8,"Distractorii folosesc o eroare de ordin de mărime (3% față de 0,3%) și o restrângere falsă a efectului circumciziei, ambele plauzibile fără lectura atentă a textului."],["partenerul receptiv","circumcizia poate reduce"]),

q("hiv-adv-002",["Virusul imunodeficienței umane (HIV):",
 ["este un lentivirus din familia retrovirusurilor","HIV-2 are o evoluție mai rapidă decât HIV-1","grupul M reprezintă 98% din infecțiile globale","multe antiretrovirale active pe HIV-1 sunt ineficiente pe HIV-2","grupul O predomină în Africa Centrală și subsahariană"],"ACD",1428,"HIV — Epidemiologie și patogenie: Virusul imunodeficienței umane",
 "Diferențierea HIV-1 de HIV-2 și cunoașterea distribuției grupurilor și subtipurilor HIV-1 relevante pentru epidemiologie și terapie.",
 ["HIV este un lentivirus din familia retrovirusurilor, caracterizat prin prezența revers-transcriptazei.","Nu: HIV-2, cu doar 40% omologie structurală cu HIV-1, pare să aibă o evoluție mai lentă decât acesta.","Grupul M reprezintă 98% din infecțiile globale, cu predominanța subtipului B în Europa, America de Nord și Australia.","Multe antiretrovirale eficiente în infecția cu HIV-1 sunt ineficiente în infecția cu HIV-2.","Nu: grupul O se limitează la un număr mic de cazuri în Camerun; în Africa Centrală și subsahariană predomină subtipurile grupului M, în special C."]],
 [8,"Testează detalii de virologie rar reținute (procentul de omologie, distribuția grupurilor), iar distractorul confundă grupul O cu subtipul C al grupului M."],["40% omologie structurală","Grupul M (subtipuri majore)"]),

q("hiv-adv-003",["NAAT pentru ARN-HIV diagnostichează infecția acută HIV:",
 ["cu 7 zile înaintea antigenului p24 și 12 zile înaintea anticorpilor","cu 12 zile înaintea antigenului p24 și 7 zile înaintea anticorpilor","simultan cu antigenul p24, cu 12 zile înaintea anticorpilor","abia după pozitivarea antigenului p24, cu 7 zile înaintea anticorpilor","concomitent cu apariția anticorpilor, la 2–4 săptămâni"],"A",1430,"HIV — Tabloul clinic în infecția HIV netratată: Infecția primară HIV",
 "Ierarhizarea temporală a testelor diagnostice (NAAT, antigen p24, anticorpi) în fereastra infecției acute HIV.",
 ["NAAT pentru ARN-HIV stabilește diagnosticul cu 7 zile înaintea testului de antigen p24 și cu 12 zile înaintea testului de anticorpi cu sensibilitate crescută.","Nu: intervalele sunt inversate; avansul este de 7 zile față de p24 și de 12 zile față de anticorpi.","Nu: NAAT precede testul de antigen p24 cu 7 zile, nu este simultan cu acesta.","Nu: NAAT se pozitivează înaintea antigenului p24, nu după acesta.","Nu: anticorpii apar în primele 2–4 săptămâni, iar NAAT precede atât anticorpii, cât și antigenul p24."]],
 [8,"Toate variantele folosesc aceleași două cifre (7 și 12 zile) și aceleași trei teste, permutate; răspunsul cere memorarea exactă a ordinii de pozitivare."],["antigen p24","limfocite reactive atipice"]),

q("hiv-adv-004",["Monitorizarea virusologică și imunologică în infecția HIV:",
 ["setpoint-ul viral se stabilește la 6 săptămâni","cel mai sensibil test detectează 20 copii ARN/ml","viremia se dozează la minimum o lună după imunizări","CD4 se dozează trimestrial la pacientul stabil sub ART, cu CD4 >350/mm³","viremia >100.000 copii/ml crește de 10 ori riscul de SIDA față de <10.000"],"BCE",1434,"HIV — Abordarea clinică a pacientului cu infecție HIV: Monitorizare",
 "Aplicarea pragurilor și intervalelor de monitorizare imunologică și virusologică și înțelegerea valorii prognostice a setpoint-ului viral.",
 ["Nu: setpoint-ul viral se stabilește la aproximativ 6 luni de la seroconversie.","Cel mai sensibil test de încărcătură virală detectează până la 20 copii de ARN viral/ml plasmă.","Creșterile tranzitorii după imunizări sau infecții intercurente impun amânarea determinării viremiei cu cel puțin o lună.","Nu: la pacientul stabil virusologic sub ART, cu CD4 peste 350/mm³, CD4 se monitorizează aproximativ o dată pe an.","Viremia peste 100.000 copii/ml crește de 10 ori riscul de progresie către SIDA în 5 ani, față de viremia constant sub 10.000 copii/ml."]],
 [8,"Combină trei praguri numerice reale cu două erori de unitate/interval (săptămâni în loc de luni, 3 luni în loc de un an) greu de sesizat fără cunoașterea exactă a textului."],["viral setpoint","20 copii de ARN viral"]),

q("hiv-adv-005",["Medicamentele antiretrovirale:",
 ["abacavirul poate da hipersensibilitate la purtătorii HLA-B*5701","nevirapina este hepatotoxică la femei cu CD4 >250 și bărbați >400","rilpivirina se indică la viremie peste 100.000 copii/ml","elvitegravirul trebuie potențat cu cobicistat","maravirocul se leagă de co-receptorul CXCR4"],"ABD",1436,"HIV — Tratamentul pacienților cu infecție HIV: Medicamente antiretrovirale (Cadranul 37.16)",
 "Recunoașterea particularităților de siguranță și de prescriere ale principalilor agenți antiretrovirali din fiecare clasă.",
 ["Abacavirul se poate asocia cu reacții de hipersensibilitate la purtătorii alelei HLA-B*5701.","Nevirapina poate determina hepatotoxicitate severă la femeile cu CD4 peste 250/mm³ și la bărbații cu CD4 peste 400/mm³.","Nu: rilpivirina se folosește doar când viremia la inițierea terapiei este sub 100.000 copii/ml.","Efectul elvitegravirului trebuie potențat („boostat”) prin asociere cu cobicistat.","Nu: maravirocul se leagă de co-receptorul CCR5 al celulei gazdă și este eficient doar pe virionii care nu folosesc CXCR4."]],
 [8,"Cere reținerea pragurilor de CD4 diferențiate pe sexe pentru nevirapină și inversează sensul pragului viremic pentru rilpivirină, o eroare frecventă."],["reacţii de hipersensibilitate","boostat potenţat cu Cobicistat"]),

q("hiv-adv-006",["Rezistența HIV la tratamentul antiretroviral:",
 ["o singură mutație poate da rezistență înaltă la INNRT","genotiparea se face după întreruperea ART","inhibitorii de protează au barieră genetică joasă","mutațiile de rezistență transmise au prevalență sub 1%","variantele rezistente dispar definitiv după oprirea medicației"],"A",1439,"HIV — Tratamentul pacienților cu infecție HIV: Rezistența la tratamentul ARV (Cadranul 37.20)",
 "Înțelegerea barierei genetice diferite între clasele ARV și a condițiilor corecte de efectuare a testelor de rezistență.",
 ["O singură mutație punctiformă poate determina rezistență înaltă la INNRT, pe când la INRT și IP rezistența necesită acumularea mai multor mutații.","Nu: după întreruperea ART varianta sălbatică redevine predominantă, de aceea genotiparea se face pe probe recoltate sub tratament.","Nu: INNRT și INSTI au barieră genetică joasă; inhibitorii de protează au, în general, o barieră genetică mai înaltă.","Nu: la pacienții cu infecție primară, prevalența mutațiilor de rezistență transmise a fost între 2 și 20%.","Nu: variantele rezistente supraviețuiesc „arhivate” și reapar la reinițierea ART și a presiunii de selecție."]],
 [8,"Distractorii inversează logica momentului genotipării și atribuie inhibitorilor de protează bariera genetică joasă a INNRT, două confuzii conceptuale frecvente."],["barieră genetică joasă","varianta sălbatică (wild type)"]),

q("hiv-adv-007",["Pneumonia cu Pneumocystis jirovecii în infecția HIV:",
 ["apare la CD4 sub 200/mm³, cu debut insidios","radiografie normală precoce, cu „sticlă mată” la CT","se diagnostichează prin cultura din lavajul bronho-alveolar","forma severă: co-trimoxazol i.v. 21 de zile, fără corticoizi","are ca profilaxie secundară standard pentamidina în aerosoli"],"AB",1443,"HIV — Afecțiuni specifice asociate cu infecția HIV: Infecția cu Pneumocystis jirovecii",
 "Corelarea pragului de CD4, a aspectului imagistic, a metodei de diagnostic și a schemei terapeutice/profilactice în pneumocistoză.",
 ["Pneumocistoza apare în general la CD4 sub 200/mm³, cu debut insidios pe parcursul câtorva săptămâni.","În stadiile incipiente radiografia pulmonară este normală, iar CT-ul cu rezoluție înaltă arată un aspect sugestiv de „sticlă mată”.","Nu: microorganismul nu poate fi cultivat in vitro; se evidențiază prin colorație argentică sau imunofluorescență.","Nu: forma severă (PaO2 sub 8 kPa) se tratează cu co-trimoxazol i.v. 120 mg/kg/zi, 21 de zile, asociat cu corticoterapie sistemică, care reduce mortalitatea.","Nu: profilaxia secundară standard este co-trimoxazolul 960 mg de trei ori pe săptămână; pentamidina în aerosoli este alternativa la intoleranța la sulfonamide."]],
 [8,"Inversează rolul co-trimoxazolului și al pentamidinei în profilaxia secundară și atribuie unui organism necultivabil un standard de diagnostic prin cultură."],["sticlă mată","coloraţie argentică"]),

q("hiv-adv-008",["Pacient cu HIV (CD4 = 35/mm³), cu scotoame și acuitate vizuală scăzută; fundul de ochi arată hemoragii și exsudate „în felie de pizza”. În acest caz:",
 ["diagnosticul de retinită CMV se stabilește clinic","foscarnetul dă mielosupresie, iar ganciclovirul nefrotoxicitate","valganciclovir oral 900 mg × 2/zi, minimum 3 săptămâni","retinita CMV apare la CD4 între 200 și 350/mm³","fără refacere imună, reactivarea duce la cecitate"],"ACE",1446,"HIV — Afecțiuni specifice asociate cu infecția HIV: Retinita cu CMV",
 "Recunoașterea retinitei CMV la pacientul cu imunodepresie profundă și cunoașterea schemei terapeutice și a toxicităților agenților anti-CMV.",
 ["Manifestările clinice sunt specifice, iar diagnosticul de retinită cu citomegalovirus se stabilește clinic.","Nu: toxicitățile sunt inversate; ganciclovirul produce mielosupresie, iar foscarnetul este nefrotoxic.","Tratamentul se face cu valganciclovir oral 900 mg × 2/zi sau ganciclovir i.v. 5 mg/kg × 2/zi, cel puțin 3 săptămâni sau până la remisia retinitei.","Nu: retinita CMV apare când CD4 scade sub 50/mm³.","Dacă imunosupresia nu este ameliorată, reactivarea este frecventă și determină cecitate."]],
 [8,"Vigneta impune corelarea CD4 = 35/mm3 cu pragul de risc și inversează toxicitățile celor doi agenți parenterali anti-CMV."],["felie de pizza","Ganciclovirul poate produce mielosupresie"]),

q("hiv-adv-009",["Pacientă cu HIV netratat (CD4 = 80/mm³) începe tratamentul antituberculos standard. În acest caz:",
 ["rifampicina inhibă citocromul P450, crescând nivelul IP","ARV se inițiază la 2 săptămâni după anti-TB","inițierea ARV se poate amâna 6 săptămâni","rifabutina, cu efect mai slab pe P450, poate înlocui rifampicina","apariția IRIS-TB impune schimbarea tratamentului antituberculos"],"BD",1448,"HIV — Afecțiuni specifice asociate cu infecția HIV: Infecția cu Mycobacterium tuberculosis",
 "Alegerea momentului inițierii ART în funcție de CD4 la pacientul cu tuberculoză și gestionarea interacțiunilor rifamicinelor cu antiretroviralele.",
 ["Nu: rifampicina este un inductor potent al citocromului P450 și reduce concentrația inhibitorilor de protează.","La CD4 sub 100/mm³, ART se inițiază la 2 săptămâni de la începerea terapiei antituberculoase.","Nu: temporizarea cu cel puțin 6 săptămâni se aplică pacienților cu CD4 peste 200/mm³, nu celor cu CD4 de 80/mm³.","Rifabutina are un efect mai slab asupra citocromului P450 și poate substitui rifampicina.","Nu: IRIS-TB nu reflectă o terapie antituberculoasă inadecvată și nu este limitat la o anumită combinație de ARV."]],
 [8,"Cere aplicarea pragului de CD4 din vignetă la două intervale diferite de inițiere a ART și inversează sensul interacțiunii rifampicină–inhibitori de protează."],["inductor potent al citocromului P450","Rifabutina are un efect mai slab"]),

q("hiv-adv-010",["Prevenirea transmiterii infecției HIV:",
 ["circumcizia reduce transmiterea la bărbați cu 20%","tenofovir-emtricitabina ca PrEP reduce riscul cu până la 90%","PEP este benefică în primele 7 zile","în studiile Partner, partenerul nedetectabil nu a transmis","variabilitatea genetică redusă a ușurat dezvoltarea vaccinului"],"BD",1450,"HIV — Prevenția și măsurile de control în infecția HIV",
 "Cuantificarea eficienței principalelor intervenții biomedicale de prevenire a HIV (circumcizie, PrEP, PEP, tratament ca prevenție).",
 ["Nu: circumcizia bărbaților heterosexuali neinfectați a redus transmiterea de la femei la bărbați cu cel puțin 50%.","Profilaxia pre-expunere cu tenofovir-emtricitabină per os, zilnic sau înaintea expunerii, reduce riscul de infectare cu până la 90%.","Nu: PEP este benefică dacă este administrată în primele 72 de ore.","Studiile Partner 1 și 2 au raportat transmisie zero de la partenerul HIV-pozitiv nedetectabil sub ART, baza mesajului „U = U”.","Nu: dezvoltarea vaccinului a fost îngreunată de variabilitatea genetică a virusului și de răspunsul imun complex al gazdei."]],
 [8,"Trei praguri numerice de eficiență/timp sunt alterate cu valori plauzibile (20% față de 50%, 7 zile față de 72 de ore), iar ultimul distractor inversează cauzalitatea."],["transmisie zero","cel puţin 50%"]),

q("hiv-adv-011",["Țintele globale UNAIDS „90-90-90” prevăd ca:",
 ["90% dintre persoanele cu HIV să fie diagnosticate","90% dintre persoanele diagnosticate să primească ARV","90% dintre cei tratați să aibă supresie virală","90% dintre cei cu supresie să fie vindecați","epidemia să fie încheiată până în 2020"],"ABC",1426,"HIV — Epidemiologie: țintele 90-90-90",
 "Recunoașterea celor trei trepte ale cascadei 90-90-90 și a orizontului 2030, fără a confunda supresia cu vindecarea.",
 ["Prima țintă este ca 90% dintre persoanele care trăiesc cu HIV să fie diagnosticate.","A doua țintă este ca 90% dintre persoanele diagnosticate să primească terapie ARV.","A treia țintă este supresia virală la 90% dintre cei tratați cu ARV.","Nu: supresia virală nu echivalează cu vindecarea funcțională, iar țintele au doar trei trepte.","Nu: textul leagă țintele 90-90-90 de încheierea epidemiei până în 2030."]],
 [8,"Adaugă o a patra treaptă inexistentă (vindecare) și mută orizontul de la 2030 la 2020."],["90-90-90","până în 2030"]),

q("hiv-adv-012",["Epidemiologia HIV în Marea Britanie, în 2017:",
 ["numărul cazurilor noi a crescut față de 2015","98% dintre diagnosticați erau sub ARV, 97% cu supresie","diagnosticul tardiv (CD4 sub 350) reprezenta 23%","circa 75% aveau altă afecțiune cronică","o treime aveau sub 30 de ani"],"BD",1426,"HIV — Epidemiologie în țările cu nivel de trai ridicat",
 "Reținerea cascadei britanice 92/98/97 și a ponderii diagnosticului tardiv (43%) versus comorbiditățile (75%).",
 ["Nu: textul descrie o scădere a numărului de cazuri noi începând din 2015.","În 2017, 98% dintre cei diagnosticați erau în tratament ARV, iar 97% dintre cei tratați aveau supresie virală.","Nu: diagnosticul tardiv (CD4 sub 350 în primele 3 luni) a rămas la 43% în 2017.","Aproximativ 75% dintre persoanele care trăiesc cu HIV au cel puțin încă o afecțiune cronică.","Nu: o treime dintre persoanele care trăiesc cu HIV au peste 50 de ani."]],
 [8,"Permutează vârsta (peste 50 versus sub 30) și inversează trendul cazurilor noi, pe fondul unor procente reale din aceeași pagină."],["43% în 2017","75% dintre cei"]),

q("hiv-adv-013",["Transmiterea verticală a HIV:",
 ["fără intervenție: 15% în Europa, până la 40% în Africa","în era pre-ARV, alăptarea dubla riscul","are în Marea Britanie un risc de 1:1000","are 90% din cazuri în țările cu trai scăzut","se produce în majoritatea cazurilor in utero"],"ABCD",1427,"HIV — Transmiterea verticală",
 "Cuantificarea riscului fără intervenție, a dublării prin alăptare și a ratei britanice 1:1000, față de predominanța perinatală.",
 ["Fără intervenție, studiile europene indică circa 15%, cu rate de până la 40% raportate în Africa și SUA.","În era pre-ARV, alăptarea dubla riscul de transmitere verticală.","În Marea Britanie, riscul actual de transmitere verticală este de 1:1000.","90% din infecțiile materno-fetale se înregistrează în țările cu nivel de trai scăzut.","Nu: majoritatea infecțiilor se produc perinatal, deși transmiterea in utero este posibilă."]],
 [8,"Inversează locul predominant al transmiterii (in-utero versus perinatal) pe fondul unor procente exacte ușor de memorat greșit."],["1:1000","alăptarea dubla riscul"]),

q("hiv-adv-014",["Patogenia infecției HIV:",
 ["gp120 se leagă de CD4 și de CCR5 sau CXCR4","limfocitele CD4+ CCR5+ intestinale sunt infectate masiv precoce","virusul circulant are timp de înjumătățire de 6 ore","anticorpii neutralizanți apar în primele 48 de ore","infectează CD4-independent astrocitele și epiteliul renal"],"ABCE",1429,"HIV — Patogenie: pătrunderea în celulă și turnover-ul viral",
 "Corelarea gp120–CD4–CCR5/CXCR4 cu depleția intestinală precoce și cu cinetică virală de 6 ore.",
 ["Receptorul recunoscut de gp120 este molecula CD4, împreună cu co-receptorii CCR5 sau CXCR4.","Limfocitele T CD4 și CCR5 pozitive din tractul gastrointestinal sunt infectate masiv încă de la început.","Timpul de înjumătățire al virusului în circulație este de circa 6 ore, cu 10⁸–10⁹ particule eliberate zilnic.","Nu: anticorpii neutralizanți apar la circa 12 săptămâni de la infecție, nu în 48 de ore.","Infecția independentă de CD4 a astrocitelor și a celulelor epiteliale renale poate deteriora aceste organe."]],
 [8,"Mută apariția anticorpilor neutralizing de la 12 săptămâni la 48 de ore, intervalul seroconversiei acute."],["aproximativ 6 ore","translocaţie microbiană"]),

q("hiv-adv-015",["„Elite controllers” sunt definiți prin menținerea, fără ARV, a unei viremii:",
 ["sub 200 copii/ml","sub 400 copii/ml","sub 2.000 copii/ml","sub 10.000 copii/ml","sub 100.000 copii/ml"],"C",1430,"HIV — Perioada de latență clinică: elite controllers",
 "Diferențierea pragului de 2.000 copii/ml al elite controllers de pragurile de laborator și de prognostic din același capitol.",
 ["Nu: definiția citată pentru elite controllers este o viremie sub 2.000 copii/ml sau nedetectabilă, menținută fără ARV.","Nu: definiția citată pentru elite controllers este o viremie sub 2.000 copii/ml sau nedetectabilă, fără ARV, nu pragul de 400.","Elite controllers sunt long-term non-progressors care mențin, fără ARV, o viremie sub 2.000 copii/ml sau chiar nedetectabilă.","Nu: 10.000 copii/ml este pragul de prognostic din monitorizare, nu definiția elite controllers.","Nu: peste 100.000 copii/ml riscul de SIDA crește de 10 ori; pragul nu definește elite controllers."]],
 [8,"Toate pragurile viremice apar în capitol; doar 2.000 copii/ml definește elite controllers."],["elite controllers","2.000 copii/ml"]),

q("hiv-adv-016",["Infecția primară HIV:",
 ["se referă la perioada de 6 săptămâni de la contactare","poate mima mononucleoza, la 3–6 săptămâni după contactare","nu modifică limfocitele CD4 și nici raportul CD4:CD8","anticorpii pot lipsi precoce, cu ARN viral și p24 detectabile","retestare după 7 zile dacă suspiciunea persistă"],"BDE",1430,"HIV — Infecția primară: clinic și diagnostic",
 "Recunoașterea ferestrei de 6 luni, a sindromului de la 3-6 săptămâni și a strategiei de retestare la 7 zile.",
 ["Nu: infecția primară se referă la perioada de 6 luni de la contactare, cu replicare rapidă și infecțiozitate ridicată.","O boală virală autolimitată, confundabilă cu mononucleoza, apare după 3–6 săptămâni și durează până la 3 săptămâni.","Nu: limfocitele CD4 pot fi scăzute semnificativ, cu inversarea raportului CD4:CD8.","În etapele timpurii anticorpii pot lipsi, deși ARN-ul viral plasmatic este crescut și antigenul p24 poate fi detectat.","Dacă testele standard sunt negative, dar suspiciunea persistă, testarea se repetă după 7 zile."]],
 [8,"Neagă limfopenia și inversarea CD4:CD8, semne de laborator reale ale fazei acute."],["6 luni de la contactarea","limfocite reactive atipice"]),

q("hiv-adv-017",["Limfadenopatia generalizată persistentă (LGP) în infecția HIV:",
 ["adenopatii >1 cm în ≥2 zone extra-inghinale, peste 3 luni","ganglionii sunt simetrici, fermi, mobili și nedureroși","biopsia ganglionară este indicată de rutină pentru diagnostic","prezența ei accelerează progresia către SIDA","adenopatia se accentuează pe măsură ce boala progresează"],"AB",1430,"HIV — Limfadenopatia generalizată persistentă",
 "Aplicarea definiției LGP (1 cm, extra-inghinal, >3 luni) și a faptului că nu modifică evoluția, biopsia nefiind de rutină.",
 ["LGP se definește ca adenopatie peste 1 cm în două sau mai multe zone extra-inghinale, peste 3 luni, fără altă cauză decât HIV.","Ganglionii sunt de obicei simetrici, fermi, mobili și nedureroși, uneori cu splenomegalie.","Nu: biopsia ganglionară nu este, în general, indicată.","Nu: prezența LGP nu pare să influențeze evoluția bolii.","Nu: pe măsură ce boala progresează, adenopatia poate să regreseze."]],
 [8,"Transformă o entitate fără impact prognostic într-un marker de progresie și face din biopsie o rutină."],[">1 cm","zone extra-inghinale"]),

q("hiv-adv-018",["Trombocitopenia izolată din infecția HIV:",
 ["poate apărea precoce, fiind o vreme singura manifestare","poate atinge 10–20 × 10⁹/L, cu echimoze","se datorează distrugerii periferice prin anticorpi antitrombocitari","se tratează de primă intenție cu corticosteroizi","se ameliorează frecvent sub ARV eficient"],"ABCE",1431,"HIV — Complicații hematologice: trombocitopenia",
 "Recunoașterea mecanismului imun periferic și a evitării corticoizilor, ARV fiind intervenția care crește trombocitele.",
 ["Trombocitopenia poate apărea precoce și poate fi, o perioadă, singura manifestare a infecției.","Numărul trombocitelor poate scădea dramatic la 10–20 × 10⁹/L, cu sângerări și echimoze.","Anticorpii circulanți antitrombocitari determină distrugerea periferică a trombocitelor.","Nu: terapia cu corticosteroizi ar trebui evitată.","ARV eficient produce frecvent creșterea numărului de trombocite."]],
 [8,"Inversează locul corticoizilor (de evitat) cu al ARV, pe fondul unui prag numeric real."],["10-20 x 109/L","corticosterozi ar trebui evitată"]),

q("hiv-adv-019",["Afectarea renală în infecția HIV:",
 ["HIVAN este mai frecventă la bărbații de rasă neagră","HIVAN este o glomerulopatie membranoasă cu tubulopatie","HIVAN poate necesita substituție renală sau transplant","tenofovirul se asociază cu sindromul Fanconi","HIVAN predomină la caucazienii cu CD4 peste 500/mm³"],"ACD",1432,"HIV — Complicații renale: HIVAN",
 "Recunoașterea profilului demografic, a FSGS cu tubulopatie și a toxicității Fanconi a tenofovirului.",
 ["Nefropatia asociată HIV este cel mai frecvent întâlnită la bărbații de rasă neagră și poate fi exacerbată de heroină.","Nu: HIVAN este o glomeruloscleroză focală segmentară, cu tubulopatie prin infectarea directă a celulelor tubulare.","HIVAN poate progresa până la insuficiență renală cu necesar de substituție sau transplant.","Tenofovirul este asociat cu sindromul Fanconi.","Nu: HIVAN este rară și caracteristică stadiilor avansate, nu caucazienilor cu CD4 înalt."]],
 [8,"Atribuie HIVAN-ul pacientului caucazian cu imunodepresie minimă, opusul profilului din text."],["bărbaţii de rasă neagră","sindromul Fanconi"]),

q("hiv-adv-020",["Testele HIV de generația a 4-a, standardul actual de testare, identifică:",
 ["anticorpii anti-HIV-1, fără anti-HIV-2","ARN-ul viral, ca testele NAAT","anticorpii anti-HIV și antigenul p24","antigenul p24, fără anticorpii anti-HIV","virusul, prin izolare în culturi celulare"],"C",1433,"HIV — Testarea HIV: teste de generația a 4-a",
 "Identificarea combinației Ac + p24 ca standard de generația a 4-a, distinct de NAAT și de culturi.",
 ["Nu: testele de generația a 4-a nu se limitează la anticorpii anti-HIV-1.","Nu: NAAT detectează genomul viral și nu este testul de generația a 4-a.","Testele de generația a 4-a identifică simultan anticorpii anti-HIV și antigenul p24.","Nu: testul de generația a 4-a include și anticorpii; antigenul p24 dispare de obicei la 8–10 săptămâni.","Nu: culturile virale sunt tehnici specializate, nu metode de screening."]],
 [8,"Permutează țintele diagnostice (Ac, p24, ARN, culturi) din același capitol de testare."],["antigenul p24","Testele moderne"]),

q("hiv-adv-021",["Anticorpii anti-HIV, ca marker de infecție:",
 ["devin detectabili în medie la 6 săptămâni","trec transplacentar la nou-născuții mamelor HIV-pozitive","dispar abia după 3 ani la nou-născuții neinfectați","dovedesc infecția activă la nou-născut, ca PCR-ul","algoritmul STARHS distinge infecția sub 130 de zile"],"ABE",1433,"HIV — Detecția anticorpilor anti-HIV",
 "Aplicarea ferestrei serologice medii de 6 săptămâni, a transferului transplacentar și a dispariției până la 18 luni la copilul neinfectat.",
 ["Anticorpii pot fi detectați după o perioadă de până la 3 luni de la infecție, în medie la 6 săptămâni.","Anticorpii traversează placenta, astfel că nou-născuții din mame HIV-pozitive îi au la naștere.","Nu: la nou-născuții neinfectați, titrul scade până la dispariție în primele 18 luni.","Nu: anticorpii nu sunt un marker de infecție activă neonatală, deoarece provin transplacentar de la mamă.","Algoritmul STARHS distinge infecția recentă (sub 130 de zile) de cea mai veche."]],
 [8,"Transformă anticorpii transplacentari într-un diagnostic de infecție neonatală activă, greșeala clasică de interpretare."],["primele 18 luni","fereastră serologică"]),

q("hiv-adv-022",["Evaluarea inițială a pacientului nou diagnosticat cu HIV:",
 ["consult de specialitate în 2 săptămâni","genotiparea se amână până la eșecul primei linii","include determinarea HLA-B*5701 printre investigațiile de bază","pacienții care refuză ARV sunt monitorizați săptămânal","proba pentru genotip se recoltează aproape de diagnostic"],"ACE",1434,"HIV — Evaluarea inițială și determinarea genotipului",
 "Reținerea ferestrei de 2 săptămâni până la specialist și a genotipării imediat după diagnostic, inclusiv HLA-B*5701.",
 ["Pacientul trebuie văzut de specialist în termen de două săptămâni, sau mai rapid dacă este simptomatic.","Nu: analiza genotipului viral este recomandată tuturor pacienților nou diagnosticați, nu după eșecul terapeutic.","HLA-B*5701 figurează printre investigațiile de bază din Marea Britanie (Cadranul 37.14).","Nu: cei care refuză ARV sunt monitorizați de 2–4 ori pe an, mai rar la CD4 crescut.","Cea mai adecvată probă pentru genotipare este cea recoltată cât mai aproape de diagnostic."]],
 [8,"Amână genotiparea până la eșec și înlocuiește intervalul 2-4 ori/an cu monitorizare săptămânală."],["două săptămâni","2-4 ori pe an"]),

q("hiv-adv-023",["Inițierea terapiei antiretrovirale:",
 ["se recomandă tuturor pacienților, indiferent de CD4","la infecție oportunistă, în 2 săptămâni de la tratarea ei","în primoinfecție, se amână până la setpoint-ul viral","aduce beneficiu demonstrat și la CD4 peste 500/mm³","se amână până când CD4 scade sub 350/mm³"],"ABD",1435,"HIV — Când trebuie inițiată terapia antiretrovirală",
 "Aplicarea indicației universale de ARV, cu inițiere imediată în primoinfecție și în 2 săptămâni după OI.",
 ["ARV trebuie oferit tuturor pacienților cu HIV, indiferent de numărul de CD4.","La o afecțiune definitorie SIDA sau o infecție oportunistă, ARV se inițiază în termen de două săptămâni de la tratamentul acesteia.","Nu: în primoinfecție, ARV trebuie inițiat imediat.","Renunțarea la pragul de CD4 s-a bazat și pe beneficiul demonstrat al ARV la CD4 peste 500.","Nu: ghidurile vechi bazate pe pragul de CD4 au fost abandonate."]],
 [8,"Reintroduce pragul vechi de 350/mm³ ca regulă actuală, contrar paragrafului de abandonare a acestor praguri."],["indiferent de numărul","peste 500"]),

q("hiv-adv-024",["Regimul ARV de primă linie la pacientul naiv:",
 ["conține un singur INRT, pentru a limita toxicitatea","două INRT plus un INSTI, IP potențat sau INNRT","are ca fundament TDF sau TAF cu emtricitabină","exclude tenofovirul la purtătorii HLA-B*57:01","monoterapia cu INSTI este suficientă sub 10.000 copii/ml"],"BC",1437,"HIV — Cu ce medicamente se inițiază terapia ARV",
 "Reținerea schemei 2 INRT + al treilea agent și a contraindicației abacavirului la HLA-B*57:01.",
 ["Nu: tratamentul se inițiază cu trei medicamente, două INRT plus un al treilea agent.","Cadranul 37.18 descrie două INRT plus un al treilea agent: INSTI, IP potențat sau INNRT.","Tenofovir-DF sau TAF plus emtricitabină reprezintă fundamentul INRT recomandat.","Nu: abacavirul, nu tenofovirul, este contraindicat la purtătorii HLA-B*57:01.","Nu: monoterapia cu INSTI nu este o schemă de primă linie."]],
 [8,"Reduce schema de trei medicamente la un singur INRT sau la monoterapie INSTI, greșeli de dezescaladare."],["trei medicamente","HLA-6*57:01"]),

q("hiv-adv-025",["Fără dolutegravir, abacavir/lamivudina (Kivexa) se recomandă la naivi doar dacă viremia inițială este:",
 ["nedetectabilă","sub 50 copii/ml","sub 10.000 copii/ml","sub 100.000 copii/ml","peste 100.000 copii/ml"],"D",1437,"HIV — INRT: Kivexa versus Truvada",
 "Reținerea pragului de 100.000 copii/ml sub care Kivexa este non-inferioară, cu excepția asocierii cu dolutegravir.",
 ["Nu: viremia nedetectabilă este ținta tratamentului, nu criteriul de alegere a Kivexa.","Nu: 50 copii/ml este pragul de supresie, nu cel de prescriere.","Nu: 10.000 copii/ml este un prag de prognostic, nu de alegere a combinației INRT.","În absența dolutegravirului, Kivexa este non-inferioară doar la viremii inițiale sub 100.000 copii/ml.","Nu: la viremie peste 100.000 copii/ml, Kivexa se folosește doar dacă Truvada este contraindicată."]],
 [8,"Toate pragurile viremice apar în capitol; doar 100.000 copii/ml condiționează Kivexa (fără dolutegravir)."],["100.000 de copii/ml","Kivexa"]),

q("hiv-adv-026",["Inhibitorii non-nucleozidici de revers-transcriptază (INNRT):",
 ["sunt eficienți împotriva HIV-2, spre deosebire de INRT","efavirenzul a devenit alternativă din cauza efectelor SNC","rilpivirina trebuie administrată pe stomacul gol","nevirapina se evită la femei cu CD4 >250 și bărbați >400","etravirina este inactivă pe tulpinile rezistente la INNRT"],"BD",1437,"HIV — Analogii non-nucleozidici de revers-transcriptază",
 "Diferențierea locului actual al efavirenzului, a restricțiilor rilpivirinei (alimente, IPP) și a pragurilor de CD4 pentru nevirapină.",
 ["Nu: INNRT sunt ineficienți împotriva HIV-2.","Efavirenzul este astăzi mai degrabă alternativă decât elecție, din cauza efectelor pe SNC (disforie, insomnie, risc suicidar).","Nu: rilpivirina trebuie administrată cu alimente, iar inhibitorii pompei de protoni sunt contraindicați.","Nevirapina nu trebuie folosită la femei cu CD4 peste 250/mm³ sau la bărbați cu CD4 peste 400/mm³.","Nu: etravirina are oarecare activitate împotriva tulpinilor rezistente la alți INNRT."]],
 [8,"Atribuie INNRT activitate pe HIV-2 (fals) și neagă activitatea reziduală a etravirinei."],["inhibitorii pompei de protoni","peste 250/mm3"]),

q("hiv-adv-027",["Inhibitorii de protează (IP) potențați:",
 ["ritonavirul sau cobicistatul blochează P450, crescând timpul de înjumătățire","atazanavirul crește bilirubina neconjugată și poate da icter","potențarea reduce riscul tulburărilor lipidice, mai ales trigliceridele","au o barieră genetică mai joasă decât INNRT","darunavirul este inactiv pe virusurile rezistente la IP"],"AB",1438,"HIV — Inhibitorii de protează",
 "Corelarea boosting-ului P450 cu hiperbilirubinemia de atazanavir, distinct de bariera genetică înaltă a IP.",
 ["Boosting-ul cu doze mici de ritonavir sau cobicistat blochează citocromul P450, crescând timpul de înjumătățire al IP.","Atazanavirul crește bilirubina neconjugată și poate produce icter.","Nu: boosting-ul crește riscul tulburărilor lipidice, în particular al trigliceridelor.","Nu: IP au, în general, o barieră genetică mai înaltă decât INNRT.","Nu: darunavirul a demonstrat activitate împotriva virusurilor rezistente la IP mai vechi."]],
 [8,"Inversează efectul boosting-ului asupra lipidelor și atribuie IP bariera joasă a INNRT."],["poate produce icter","barieră genetică mai înaltă"]),

q("hiv-adv-028",["Monitorizarea după inițierea ARV:",
 ["la 4 săptămâni, viremia scade cu cel puțin 1 log10","supresia sub 50 copii/ml se obține în 4 săptămâni","viremia se reevaluează la 1, 3 și 6 luni","CD4 se evaluează la 3 luni, apoi la 3–4 luni","după supresie, viremia se dozează săptămânal"],"ACD",1438,"HIV — Monitorizarea terapiei ARV",
 "Aplicarea cineticilor 1 log la 4 săptămâni și <50 copii/ml la 12-24 săptămâni, plus calendarul de reevaluare.",
 ["După 4 săptămâni, încărcătura virală ar trebui să scadă cu cel puțin 1 log10 copii/ml.","Nu: supresia sub 50 copii/ml ar trebui obținută între săptămânile 12 și 24.","Viremia se reevaluează la 1, 3 și 6 luni de la inițierea ARV.","CD4 se evaluează la 3 luni de la inițiere, apoi la intervale de 3–4 luni.","Nu: după supresie, în stabilitate, viremia se evaluează la fiecare 6 luni."]],
 [8,"Înlocuiește intervalul de 6 luni după supresie cu dozări săptămânale, o intensificare nejustificată."],["1 log10 copii/ml","<50 copii/ml"]),

q("hiv-adv-029",["Eșecul virusologic și schimbarea ARV:",
 ["eșecul: două viremii succesive peste 400 copii/ml","un singur agent nou activ este suficient","la intoleranță cu viremie nedetectabilă, switch în aceeași clasă","ARV nu se întrerupe nici în toxicitate cumulativă","efavirenzul și nevirapina se pot opri înaintea celorlalte componente"],"ACE",1440,"HIV — Eșecul terapeutic, switch și întrerupere",
 "Aplicarea pragului dublu de 400 copii/ml, a regulii celor doi agenți noi și a opririi eșalonate a INNRT cu timp de înjumătățire lung.",
 ["Eșecul virusologic se definește prin două determinări succesive peste 400 copii/ml la un pacient anterior suprimat.","Nu: noul regim trebuie bazat pe cel puțin doi agenți noi la care virusul este sensibil.","Dacă viremia este nedetectabilă și un medicament nu este tolerat, se face switch în aceeași clasă, la un agent la care virusul este sensibil.","Nu: întreruperea ARV este indicată în toxicitatea cumulativă sau în interacțiunile urgente.","Efavirenzul și nevirapina, cu timp de înjumătățire lung, pot necesita oprirea înaintea celorlalte componente."]],
 [8,"Interzice întreruperea pe care textul o recomandă în toxicitate și cere reținerea pragului dublu de 400 copii/ml."],["peste 400 copii/ml","timp de înjumătăţire lung"]),

q("hiv-adv-030",["Hipersensibilitatea la abacavir, legată de HLA-B*5701, apare de obicei în:",
 ["primele 6 săptămâni de la inițiere","primele 48 de ore de la inițiere","luna a 6-a de tratament","al doilea an de tratament","cazul reinițierii, nu la prima expunere"],"A",1440,"HIV — Reacții alergice: hipersensibilitatea la abacavir",
 "Reținerea ferestrei de 6 săptămâni a HSR la abacavir și a contraindicației de reinițiere.",
 ["Reacția de hipersensibilitate la abacavir apare de obicei în primele 6 săptămâni de la inițiere.","Nu: nu este descrisă ca o anafilaxie IgE în primele 48 de ore; apare de obicei în primele 6 săptămâni.","Nu: reacția nu ține de IRIS; apare de obicei în primele 6 săptămâni.","Nu: toxicitatea mitocondrială aparține altor INRT; hipersensibilitatea apare în primele 6 săptămâni.","Nu: poate apărea la prima expunere; reinițierea este contraindicată deoarece poate fi fatală."]],
 [8,"Permutează fereastra de 6 săptămâni cu alte intervale reale din același capitol (48 h, IRIS, toxicitate tardivă)."],["primele 6 săptămâni","HLA-8 5701"]),

q("hiv-adv-031",["Complicațiile metabolice ale ARV și IRIS:",
 ["simvastatina este statina de elecție sub tratament cu IP","stavudina și zidovudina cresc riscul de lipoatrofie","în TB și criptococoză, tratamentul specific precede ARV, în medie, cu 4 săptămâni","acidoza lactică impune continuarea ARV în doze reduse","TAF are toxicitate osoasă mai mare decât TDF"],"BC",1440,"HIV — Lipodistrofie, toxicitate mitocondrială și IRIS",
 "Recunoașterea contraindicației simvastatinei cu IP, a ferestrei IRIS de 4 săptămâni și a avantajului osos al TAF.",
 ["Nu: simvastatina este contraindicată din cauza interacțiunilor cu IP.","Stavudina și zidovudina determină un risc crescut de lipoatrofie.","Pentru a reduce IRIS în tuberculoză și criptococoză, tratamentul specific se administrează în medie cu 4 săptămâni înaintea ARV.","Nu: toxicitatea mitocondrială cu acidoză lactică impune întreruperea imediată a ARV.","Nu: tenofovir alafenamida (TAF) pare să aibă toxicitate osoasă mai redusă decât TDF."]],
 [8,"Transformă simvastatina contraindicată în agent de elecție și cere continuarea ARV în acidoza lactică, o urgență de întrerupere."],["Simvastatina este contraindicată","lipoatrofie"]),

q("hiv-adv-032",["Gravidă cu HIV, sub ARV, cu viremie sub 50 copii/ml și travaliu necomplicat. În acest caz:",
 ["riscul de transmitere este circa 0,1% în Marea Britanie","nașterea vaginală nu crește riscul față de cezariană","nou-născutul primește zidovudină sirop timp de 4 săptămâni","mama este sfătuită să alăpteze, riscul fiind scăzut","cezariana rămâne calea de naștere de elecție"],"ABC",1441,"HIV — Sarcina: transmitere, naștere și alăptare",
 "Aplicarea ratei 0,1% la VL<50, a nașterii vaginale acceptabile și a zidovudinei 4 săptămâni la nou-născut.",
 ["La femeile sub ARV cu viremie sub 50 copii/ml, rata de transmitere în Marea Britanie este de circa 0,1%.","Nașterea vaginală nu crește riscul de transmitere dacă ARV este eficient și nu apar complicații.","Nou-născutul primește zidovudină sirop timp de 4 săptămâni.","Nu: mamele sunt încă sfătuite să nu alăpteze, deși riscul sub ARV eficient este extrem de scăzut.","Nu: cezariana a redus riscul în era pre-ARV, dar nu mai este impusă la viremie nedetectabilă."]],
 [8,"Reintroduce cezariana universală din era pre-ARV, ignorând rata 0,1% și nașterea vaginală acceptată."],["0,1%","zidovudină sirop"]),

q("hiv-adv-033",["Profilaxia post-expunere (PEP) în Marea Britanie:",
 ["poate fi benefică în primele 72 de ore","constă în Truvada cu raltegravir, 4 săptămâni","se recomandă și când sursa are sub 200 copii/ml","poate înlocui prezervativul la parteneri cu viremie nedetectabilă","nu necesită testarea HIV prealabilă a persoanei expuse"],"AB",1441,"HIV — Profilaxia post-expunere",
 "Aplicarea ferestrei de 72 de ore, a schemei Truvada+raltegravir 4 săptămâni și a non-indicației când sursa are VL<200.",
 ["PEP poate fi benefică dacă este administrată în primele 72 de ore.","Regimul standard britanic este Truvada plus raltegravir, timp de 4 săptămâni.","Nu: dacă sursa are viremie nedetectabilă (sub 200 copii ARN HIV/ml), PEP nu este recomandată.","Nu: PEP nu trebuie să înlocuiască celelalte metode de protecție.","Nu: persoanele la risc trebuie testate HIV înainte de începerea PEP."]],
 [8,"Transformă PEP într-un substitut al prezervativului și anulează testarea prealabilă, pe fondul pragului VL<200 ușor de ignorat."],["primele 72 de ore","<200 copii ARN HIV"]),

q("hiv-adv-034",["Vaccinarea adultului cu infecție HIV (Cadranul 37.22):",
 ["vaccinurile vii se preferă la CD4 sub 200/mm³","vaccinurile vii se evită sub 200 CD4/mm³, prudență sub 350","vaccinul gripal inactivat se recomandă anual tuturor","ROR și varicela se administrează indiferent de CD4","vaccinul hepatitic B se recomandă tuturor neimunizaților"],"BCE",1443,"HIV — Vaccinarea la adulții cu infecție HIV",
 "Aplicarea pragului CD4<200 pentru interdicția vaccinurilor vii și a indicațiilor anuale (gripă) și universale (VHB).",
 ["Nu: vaccinurile vii atenuate nu trebuie administrate la CD4 sub 200/mm³.","Vaccinurile viu atenuate nu trebuie administrate la CD4 sub 200/mm³ și se folosesc cu atenție sub 350/mm³.","Vaccinul gripal inactivat se recomandă anual tuturor pacienților.","Nu: ROR și varicela sunt vaccinuri vii, iar administrarea lor ține cont de pragul de CD4.","Vaccinul anti-hepatită B, cu subunitate virală, se recomandă tuturor neimunizaților."]],
 [8,"Inversează regula vaccinurilor vii (contraindicate, nu preferate, la CD4<200)."],["CD4 <200/mm3","Viu atenuat"]),

q("hiv-adv-035",["Meningita criptococică la pacientul cu HIV:",
 ["poate evolua fără redoare de ceafă și fotofobie","se tratează inițial cu amfotericină B liposomală ± flucitozină","are corticoterapia sistemică drept adjuvant de rutină","impune inițierea ARV imediat, odată cu antifungicul","fluconazol până la 1 an, cu VL nedetectabilă și CD4 >100"],"ABE",1444,"HIV — Criptococoza",
 "Recunoașterea meningismului absent, a schemei amfotericină±flucitozină și a amânării ARV 4 săptămâni, fără steroizi.",
 ["Redoarea de ceafă și fotofobia pot lipsi, răspunsul inflamator fiind alterat.","Tratamentul inițial este amfotericină B liposomală 4,0 mg/kg/zi i.v., cu sau fără flucitozină.","Nu: corticoterapia nu este recomandată în meningita criptococică.","Nu: ARV se inițiază la circa 4 săptămâni, pentru a reduce riscul de IRIS.","Întreținerea cu fluconazol continuă până la 1 an, cu viremie nedetectabilă și CD4 constant peste 100/mm³."]],
 [8,"Importă corticoterapia din pneumocistoză, contraindicată aici, pe fondul unor praguri CD4 și intervale reale."],["amfotericină B liposomală","Nu se recomandă utilizarea corticoterapiei"]),

q("hiv-adv-036",["Doza de încărcare de pirimetamină în toxoplasmoza cerebrală este:",
 ["50 mg","100 mg","200 mg","400 mg","800 mg"],"C",1445,"HIV — Toxoplasmoza: tratament",
 "Reținerea dozei de încărcare de 200 mg, distinctă de întreținerea de 50 mg și de alte doze din capitol.",
 ["Nu: 50 mg este doza zilnică de întreținere, administrată cel puțin 6 săptămâni.","Nu: 100 mg nu este doza de încărcare citată, care este de 200 mg.","Pirimetamina se administrează cu o doză de încărcare de 200 mg, apoi 50 mg zilnic cel puțin 6 săptămâni.","Nu: 400 mg este doza de fluconazol i.v. din criptococoză, nu doza de pirimetamină.","Nu: doza de încărcare a pirimetaminei este de 200 mg, urmată de 50 mg zilnic."]],
 [8,"Permutează 200 mg (încărcare) cu 50 mg (întreținere) și cu doze reale ale altor antimicrobiene din aceleași pagini."],["doză de încărcare 200 mg","50 mg zilnic"]),

q("hiv-adv-037",["Criptosporidioza la pacientul cu HIV:",
 ["poate da diaree apoasă severă și persistentă","se poate asocia cu colangită sclerozantă","chisturile se vizualizează în scaun prin colorație argentică","are ca tratament de elecție nitazoxanida","are ca tratament de elecție ARV"],"ABE",1445,"HIV — Criptosporidioza",
 "Recunoașterea colorației Kinyoun și a faptului că ARV, nu antiparazitarul, este tratamentul de elecție.",
 ["Criptosporidioza poate provoca diaree apoasă severă și persistentă, cu anorexie, dureri, greață și vărsături.","Criptosporidioza se poate asocia cu colangită sclerozantă.","Nu: chisturile se vizualizează în materiile fecale cu colorația Kinyoun.","Nu: nitazoxanida și paromomicina pot avea un oarecare efect, dar tratamentul de elecție este ARV.","Refacerea imunologică prin ARV eficient este tratamentul de elecție și determină de obicei remisia."]],
 [8,"Inversează ierarhia terapeutică, făcând din nitazoxanidă cura și din ARV o măsură amânabilă."],["coloraţiei Kinyoun","tratamentul de elecţie"]),

q("hiv-adv-038",["Co-infecția HIV cu virusurile hepatitice:",
 ["5–15% au hepatită B cronică, o treime au VHC","nou-diagnosticații se testează pentru VHA, VHB și VHC","boala hepatică progresează mai lent decât în mono-infecție","DAA 12 săptămâni obțin SVR peste 90%","ARV se amână până după vindecarea VHC"],"ABD",1445,"HIV — Co-infecția cu virusuri hepatitice B și C",
 "Cuantificarea prevalențelor 5-15% VHB și ~1/3 VHC, a vaccinării universale și a SVR>90% la 12 săptămâni de DAA.",
 ["La nivel global, 5–15% dintre pacienții cu HIV au hepatită B cronică, iar circa o treime au infecție cu VHC.","Toți nou-diagnosticații se testează pentru VHA, VHB și VHC, iar neimunizații se vaccinează anti-A și anti-B.","Nu: progresia bolii hepatice este mai rapidă decât în mono-infecție.","DAA pentru VHC se administrează 12 săptămâni, cu SVR peste 90%.","Nu: toți co-infectații HIV/VHC trebuie să primească ARV; dacă sunt planificate DAA, ARV se începe cu 4–6 săptămâni înainte."]],
 [8,"Amână ARV până după VHC, opusul recomandării de a începe ARV cu 4-6 săptămâni înaintea DAA."],["5-15%","aproximativ o treime"]),

q("hiv-adv-039",["Colita cu citomegalovirus în infecția HIV:",
 ["apare tipic la CD4 între 200 și 350/mm³","are la histologie incluziuni în „ochi de bufniță”","ganciclovir i.v. 5 mg/kg × 2/zi, 14–28 de zile","necesită menținere și după refacerea imună prin ARV","durere abdominală, diaree cu sânge, mucoasă friabilă"],"BCE",1446,"HIV — Afecțiuni gastrointestinale cu CMV",
 "Recunoașterea incluziunilor „ochi de bufniță” și a schemei ganciclovir 14-28 de zile, fără menținere după reconstituția imună.",
 ["Nu: boala CMV apare la CD4 constant sub 100/mm³, iar retinita sub 50/mm³.","Incluziunile în „ochi de bufniță” la examenul histologic sunt caracteristice.","Tratamentul este ganciclovir 5 mg/kg × 2/zi i.v., timp de 14–28 de zile.","Nu: terapia de menținere nu mai este necesară după ameliorarea imună prin ARV.","Colita CMV produce durere abdominală, diaree cu sânge și mucoasă colonică friabilă sau ulcerată."]],
 [8,"Mută colita CMV la pragul de CD4 al pneumocistozei și prelungește inutil terapia de menținere."],["ochi de bufniţă","14-28 de zile"]),

q("hiv-adv-040",["Leucoencefalopatia multifocală progresivă (PML):",
 ["este produsă de poliomavirusul JC, care infectează oligodendrocitele","are leziuni care captează contrastul, cu efect de masă","are leziuni T2 hiperintense, RMN fiind superior CT","are cidofovirul ca tratament specific de elecție","se confirmă de regulă prin PCR JC în LCR și imagistică, fără biopsie"],"ACE",1447,"HIV — Infecția cu poliomavirusul JC: PML",
 "Corelarea virusului JC cu leziunile fără contrast/masă și cu absența unui antiviral specific, ARV fiind singura intervenție.",
 ["PML se datorează poliomavirusului JC, care infectează oligodendrocitele.","Nu: leziunile din PML nu captează contrastul și nu produc efect de masă.","RMN este mai sensibil decât CT și arată leziuni hiperintense T2 în substanța albă.","Nu: nu există tratament specific; ARV eficient este singura intervenție care poate induce remisia.","PCR pentru virusul JC în LCR plus imagistica sunt de regulă suficiente, biopsia nemaifiind necesară."]],
 [8,"Introduce cidofovirul ca elecție, deși textul afirmă absența tratamentului specific."],["Poliomavirusul JC","nu produc efect de masă"]),

q("hiv-adv-041",["Infecția diseminată cu Mycobacterium avium-intracellulare (MAI):",
 ["apare în stadii avansate, cu imunodepresie foarte severă","pătrunde digestiv sau pulmonar și diseminează prin macrofage","se tratează frecvent cu etambutol, rifabutină și claritromicină","răspunde la regimul antituberculos standard de primă linie","profilaxia primară o întârzie, fără creșterea supraviețuirii"],"ABCE",1448,"HIV — Infecția cu Mycobacterium avium-intracellulare",
 "Recunoașterea rezistenței la anti-TB standard și a combinației etambutol–rifabutină–claritromicină, plus limita profilaxiei.",
 ["Infecția diseminată cu MAI apare în stadii avansate, cu imunodepresie foarte severă.","Poarta de intrare este tractul digestiv sau plămânii, cu diseminare prin macrofage.","O combinație des întâlnită este etambutol, rifabutină și claritromicină.","Nu: MAI este rezistent la tratamentul antituberculos standard.","Profilaxia primară cu rifabutină sau azitromicină poate întârzia apariția infecției, fără creștere demonstrată a supraviețuirii."]],
 [8,"Atribuie MAI sensibilitatea la HREZ, opusul rezistenței declarate, pe fondul unei combinații reale de macrolid și rifabutină."],["Etambutolul poate fi util","claritromicină sau azitromicină"]),

q("hiv-adv-042",["Agentul implicat în patogenia sarcomului Kaposi epidemic este:",
 ["virusul Epstein-Barr (EBV)","virusul herpetic uman 8","virusul papiloma uman (HPV)","poliomavirusul JC","citomegalovirusul (CMV)"],"B",1449,"HIV — Sarcomul Kaposi",
 "Asocierea SK epidemic cu HHV-8, distinct de EBV, HPV, JC și CMV, toate virusuri cu manifestări proprii în HIV.",
 ["Nu: EBV se asociază cu limfoamele, nu cu sarcomul Kaposi.","Virusul herpetic uman 8 (HHV-8) este implicat în patogenia sarcomului Kaposi.","Nu: HPV este legat de neoplazia cervicală și anală.","Nu: virusul JC produce leucoencefalopatia multifocală progresivă.","Nu: CMV produce retinită și colită, nu sarcom Kaposi."]],
 [8,"Permutează cele cinci virusuri oncogene/oportuniste din aceleași pagini între tumorile și infecțiile pe care le cauzează."],["HHV-8","nuanţa violacee"]),

q("hiv-adv-043",["Neoplaziile asociate infecției HIV:",
 ["limfoamele sunt mai ales Hodgkin, frecvent extraganglionare","o mare parte dintre limfoame sunt asociate cu EBV","la femei se recomandă anual citologie cervicală","sarcomul Kaposi visceral are prognostic mai bun decât cutanat","ARV favorizează regresia leziunilor de sarcom Kaposi"],"BCE",1449,"HIV — Limfoame, carcinom cervical și sarcom Kaposi",
 "Recunoașterea profilului LNH extra-ganglionar EBV-asociat, a citologiei anuale și a regresiei SK sub ARV, cu prognostic rezervat al formei viscerale.",
 ["Nu: limfoamele sunt în majoritate non-Hodgkin cu celulă mare B, frecvent extraganglionare (creier, plămân, tub digestiv).","O mare parte dintre limfoame sunt asociate EBV, cu exprimarea antigenelor nucleare latente EBNA 1–6.","Femeile cu HIV au risc crescut de neoplasm de col, fiind recomandată citologia cervicală anuală.","Nu: sarcomul Kaposi visceral are un prognostic mai rezervat decât forma cutanată.","Terapia ARV favorizează regresia leziunilor de sarcom Kaposi."]],
 [8,"Inversează prognosticul SK visceral versus cutanat, pe fondul unor asocieri virale reale."],["EBNA 1-6","citologiei cervicale"]),

q("hiv-adv-044",["Testarea HIV și diagnosticul tardiv în Marea Britanie:",
 ["în 2017, circa 8% erau nediagnosticați","testarea nou-înregistraților în asistența primară la prevalență >2/1.000","testele reactive la domiciliu nu necesită confirmare","23% aveau la diagnostic CD4 sub 200/mm³","inițierea tardivă este principalul predictor de morbiditate și mortalitate"],"ABDE",1449,"HIV — Extinderea testării și diagnosticul tardiv",
 "Reținerea ponderilor 8% nediagnosticați, 43% tardiv, 23% CD4<200 și a pragului populațional 2/1.000 pentru testare universală.",
 ["În 2017, circa 8% dintre persoanele cu HIV erau nediagnosticate, iar 43% dintre noile diagnostice erau tardive (CD4 sub 350).","Testarea se recomandă tuturor nou-înregistraților în asistența primară și în urgență acolo unde seroprevalența depășește 2/1.000.","Nu: testele reactive la domiciliu sau point-of-care necesită confirmare serologică, din cauza ratei semnificative de rezultate fals-pozitive.","23% dintre pacienți au avut CD4 sub 200/mm³ la diagnostic.","Inițierea tardivă a tratamentului este cel mai important predictor al morbidității și mortalității."]],
 [8,"Anulează necesitatea confirmării testelor rapide, deși textul subliniază fals-pozitivele, și cere reținerea a trei procente din același paragraf."],["2/1.000","43% dintre pacienţii"]),

q("hiv-adv-045",["Prevenirea transmiterii HIV, dincolo de PrEP:",
 ["cazurile noi provin mai ales de la pacienți nedetectabili","variabilitatea genetică redusă a ușurat dezvoltarea vaccinului","echipamentul steril de injectare a avut efecte favorabile","testele de domiciliu reactive impun confirmare serologică","infecția recentă cu viremie înaltă este foarte contagioasă"],"CDE",1450,"HIV — Strategii de reducere a transmiterii",
 "Recunoașterea rolului nediagnosticatului și al infecției recente în lanțul de transmitere, plus confirmarea testelor de domiciliu.",
 ["Nu: modelele britanice atribuie marea majoritate a cazurilor noi persoanelor nediagnosticate sau cu infecție recentă.","Nu: dezvoltarea vaccinului a fost îngreunată de variabilitatea genetică a virusului.","Furnizarea de echipament steril de injectare a avut efecte favorabile acolo unde a fost implementată.","Testele de domiciliu reactive impun confirmare serologică și programare rapidă la specialist.","Persoanele cu infecție recentă și viremie înaltă au o contagiozitate deosebit de ridicată."]],
 [8,"Inversează obstacolul vaccinului (variabilitatea genetică) și cere integrarea datelor de testare de pe pagina alăturată."],["cel puţin 50%","nedetectabil = netransmisibil"]),

q("hiv-adv-046",["Estimările globale ale epidemiei HIV, de la descrierea SIDA (1981):",
 ["peste 78 de milioane de persoane infectate","39 de milioane de decese","36,9 milioane de persoane care trăiesc cu HIV","21,7 milioane de persoane infectate în total","sub 10 milioane trăiesc cu HIV"],"ABC",1425,"HIV — Epidemiologie globală: bilanț istoric",
 "Reținerea trio-ului 78 milioane infectați / 39 milioane decese / 36,9 milioane trăiesc cu HIV, distinct de 21,7 milioane aflați sub ARV de pe pagina următoare.",
 ["Se estimează că peste 78 de milioane de persoane au fost infectate de-a lungul timpului.","Textul citează 39 de milioane de decese.","La cea mai recentă estimare, 36,9 milioane de oameni trăiesc cu HIV.","Nu: 21,7 milioane este numărul celor cu acces la ARV, nu totalul celor infectați vreodată.","Nu: prevalența globală este de 36,9 milioane de persoane care trăiesc cu HIV."]],
 [8,"Permutează 21,7 milioane (ARV) peste bilanțul istoric 78/39/36,9, trei cifre de pe aceeași deschidere de capitol."],["78 de milioane","36,9 milioane"]),

q("hiv-adv-047",["Epidemia HIV în Africa subsahariană:",
 ["Africa de Sud și de Est: 6,2% din populația globului, peste jumătate din cazuri","aici apar anual 43% din cazurile noi de HIV","Swaziland are prevalența maximă: 27,2% la adulții 15–49 ani","transmiterea se face predominant prin droguri injectabile","prevalența este similară la femei și la bărbați"],"ABC",1426,"HIV — Epidemiologie: Africa subsahariană",
 "Cuantificarea disproporției 6,2% populație versus >50% din cazuri și 43% din incidente, plus prevalența 27,2% din Swaziland.",
 ["Africa de Sud și de Est adăpostește 6,2% din populația globului, dar peste jumătate din persoanele diagnosticate cu HIV.","În fiecare an se înregistrează aici 43% din cazurile noi de HIV.","Swaziland are cea mai mare prevalență mondială, 27,2% dintre adulții de 15–49 de ani.","Nu: calea predominantă de transmitere în regiune este contactul heterosexual.","Nu: infecția este aproape de două ori mai frecventă la femeile tinere (3,2%) decât la bărbați (1,6%)."]],
 [8,"Înlocuiește calea heterosexuală cu drogurile injectabile și anulează gradientul pe sexe, pe fondul a trei procente reale."],["6,2% din populaţia","27,2% dintre adulţii"]),

q("hiv-adv-048",["În Africa subsahariană, prevalența HIV la femeile tinere față de bărbați este:",
 ["aproape dublă (3,2% față de 1,6%)","identică, de 1,6% la ambele sexe","mai mică (0,8% față de 3,2%)","de trei ori mai mare (4,8% față de 1,6%)","legată de transmiterea verticală, nu heterosexuală"],"A",1426,"HIV — Epidemiologie: gradientul pe sexe în Africa",
 "Reținerea prevalențelor 3,2% la femeile tinere versus 1,6% la bărbați, pe fondul transmiterii heterosexuale predominante.",
 ["Prevalența la femeile tinere este aproape dublă: în medie 3,2% față de 1,6% la bărbați.","Nu: valorile nu sunt identice; 3,2% la femeile tinere față de 1,6% la bărbați.","Nu: direcția este inversată; prevalența este mai mare la femeile tinere (3,2%) decât la bărbați (1,6%).","Nu: prevalența la femeile tinere este aproape dublă (3,2% față de 1,6%), nu triplă.","Nu: explicațiile sunt complexe, dar calea predominantă de transmitere este contactul heterosexual."]],
 [8,"Permutează 3,2% și 1,6% între sexe și mută gradientul pe grupe de vârstă din alte paragrafe epidemiologice."],["3,2%","1,6%"]),

q("hiv-adv-049",["Ghidurile britanice (Cadranul 37.9) recomandă testarea HIV universală în:",
 ["clinicile de ginecologie și de boli sexual transmisibile","serviciile prenatale și cele de întrerupere a sarcinii","centrele pentru persoanele dependente de droguri","serviciile pentru tuberculoză, hepatite B și C, limfom","cabinetele de familie din zone cu prevalență sub 0,1/1.000"],"ABCD",1427,"HIV — Indicațiile testării: servicii cu testare universală",
 "Recunoașterea setărilor de testare universală (BTS, prenatal, droguri, TB/VHB/VHC/limfom) versus pragul de prevalență înaltă din asistența primară.",
 ["Clinicile de ginecologie și de boli cu transmitere sexuală sunt listate pentru testarea universală.","Serviciile de consultații prenatale și secțiile unde se practică întreruperi de sarcină sunt listate.","Centrele pentru persoanele dependente de droguri sunt listate.","Serviciile de îngrijire pentru tuberculoză, hepatită B și C și limfom sunt listate.","Nu: în asistența primară testarea universală vizează zonele cu prevalență înaltă (≥2/1.000), nu pe cele cu prevalență foarte mică."]],
 [8,"Mută pragul de 2/1000 al asistenței primare spre o prevalență neglijabilă, pe fondul unei liste reale de servicii universale."],["Clinicile de ginecologie","prevalenţă înaltă"]),

q("hiv-adv-050",["La expunerea inițială, infecția HIV permanentă se stabilește de obicei prin:",
 ["celulele dendritice, care duc virusul fondator spre ganglioni","infecția directă a miocitelor scheletice, fără pasaj ganglionar","integrarea virusului în genomul eritrocitelor mature","colonizarea keratinocitelor, fără implicarea celulelor dendritice","replicarea virusului în trombocitele circulante"],"A",1429,"HIV — Patogenie: virusul fondator și celulele dendritice",
 "Recunoașterea traseului mucoasă → celule dendritice → ganglion regional, cu un virus fondator care stabilește infecția permanentă.",
 ["Celulele dendritice de pe mucoase transportă virusul spre ganglionii limfatici regionali, infecția fiind stabilită de obicei de un „virus fondator”.","Nu: miocitele scheletice nu sunt poarta descrisă; virusul este transportat de celulele dendritice spre ganglionii regionali.","Nu: eritrocitele mature nu au nucleu și nu sunt ținta de integrare descrisă.","Nu: celulele dendritice, nu keratinocitele, transportă virusul spre ganglionii regionali.","Nu: trombocitele nu sunt rezervorul în care se stabilește infecția permanentă."]],
 [8,"Înlocuiește traseul dendritice–ganglion cu ținte celulare absente din paragraf (miocit, eritrocit, trombocit)."],["virus fondator","celulele dendritice"]),

q("hiv-adv-051",["Cinetica virală și răspunsul imun în infecția HIV:",
 ["producția virală a celulei durează circa 2 zile","efectele NK sunt compromise de mutațiile de scăpare","anticorpii neutralizanți apar la circa 12 săptămâni","anticorpii neutralizanți apar în primele 48 de ore","celulele NK elimină virusul fondator înainte de integrare"],"ABC",1429,"HIV — Patogenie: cinetică celulară, NK și anticorpi",
 "Corelarea duratei de 2 zile a producției virale cu limitele NK (mutații de scăpare) și cu apariția anticorpilor neutralizanți la 12 săptămâni.",
 ["Producția de virus de către celulele infectate durează aproximativ 2 zile, fiind probabil limitată de moartea celulei.","Celulele NK sunt implicate, dar mutațiile de scăpare ale populației virale le compromit efectele antivirale.","Anticorpii neutralizanți apar la aproximativ 12 săptămâni de la infecție.","Nu: anticorpii neutralizanți apar la aproximativ 12 săptămâni, nu în 48 de ore.","Nu: textul nu atribuie celulelor NK eliminarea virusului fondator; efectele lor sunt compromise de mutațiile de scăpare."]],
 [8,"Mută anticorpii de la 12 săptămâni la 48 de ore (fereastra infecției acute) și supraestimează NK."],["aproximativ 2 zile","12 săptămâni"]),

q("hiv-adv-052",["Sistemele de clasificare OMS și CDC ale infecției HIV:",
 ["servesc supravegherii, nu asistenței clinice de rutină","stadiile CDC 0–3 combină serologia, CD4 și condițiile SIDA","înlocuiesc viremia și CD4 în decizia de inițiere a ARV la fiecare vizită","stadiul CDC 0 înseamnă SIDA cu CD4 sub 50/mm³","sistemul OMS nu include testul de anticorpi anti-HIV"],"AB",1430,"HIV — Clasificarea OMS și CDC",
 "Recunoașterea rolului de supraveghere (nu de rutină clinică) și a componentelor stadiilor CDC 0-3.",
 ["Sunt cele mai utilizate, iar aplicabilitatea lor principală este monitorizarea și supravegherea populației, mai degrabă decât asistența clinică de rutină.","Clasificarea CDC (stadiile 0–3) combină serologia HIV pozitivă, numărul de CD4 și condițiile care definesc SIDA.","Nu: textul le delimitează de asistența clinică de rutină; aplicabilitatea lor principală este supravegherea populației.","Nu: stadiile CDC 0–3 combină criterii de laborator și clinice; stadiul 0 nu este definit ca SIDA cu CD4 sub 50/mm³.","Nu: sistemul OMS include un test de anticorpi anti-HIV pozitiv."]],
 [8,"Transformă instrumentele de supraveghere în criterii de prescriere ARV și inversează conținutul stadiului 0."],["Centrului pentru controlul bolilor","stadiile 0-3"]),

q("hiv-adv-053",["Complexul demenței asociate SIDA (ADC) și polineuropatia senzitivă:",
 ["ADC variază de la tulburări de memorie la deficit sever","pot apărea mielopatie vacuolară și atrofie cerebrală","LCR este de obicei normal, uneori cu proteine crescute","polineuropatia senzitivă predomină la membrele superioare","EEG arată complexe periodice trifazice, patognomonice"],"ABC",1431,"HIV — ADC, mielopatie vacuolară și polineuropatie",
 "Recunoașterea spectrului ADC, a mielopatiei vacuolare și a LCR-ului adesea normal, plus polineuropatia dureroasă de picioare.",
 ["ADC variază de la pierderi ușoare de memorie până la deficit cognitiv sever, tulburări de personalitate și lentoare psihomotorie.","Histologic se poate observa mielopatie vacuolară la nivelul măduvei; CT arată atrofie cerebrală, iar RMN leziuni T2 hiperintense în substanța albă.","LCR este de obicei normal, deși poate exista o creștere a proteinelor.","Nu: polineuropatia senzitivă apare în stadii avansate, predominant la membrele inferioare, cu durere intensă la picioare în formele severe.","Nu: EEG evidențiază modificări nespecifice de encefalopatie, nu complexe patognomonice."]],
 [8,"Atribuie EEG-ului un pattern patognomonic pe care textul îl califică nespecific, pe fondul unor semne imagistice reale."],["mielopatiei vacuolare","Polineuropatia senzitivă"]),

q("hiv-adv-054",["Leucoplazia păroasă orală, asociată EBV, apare:",
 ["pe marginile laterale ale limbii, ca zone albicioase reliefate","pe palatul dur, sub forma unor peteșii hemoragice","ca ulcerații aftoase dureroase pe pilierii amigdalieni","ca depozit alb detersabil pe fața dorsală a limbii","ca leziuni violacee nodulare la nivelul conjunctivei"],"A",1447,"HIV — Leucoplazia păroasă orală (EBV)",
 "Localizarea leucoplaziei păroase pe marginile laterale ale limbii, distinct de candidoză, afte și Kaposi.",
 ["Leziunile apar intermitent pe marginile laterale ale limbii sau pe mucoasa bucală, ca zone albicioase și reliefate.","Nu: peteșiile palatine nu descriu leucoplazia păroasă, care apare pe marginile laterale ale limbii.","Nu: ulcerațiile aftoase sunt o altă manifestare mucoasă, distinctă de leucoplazia păroasă.","Nu: depozitul detersabil este al candidozei; leucoplazia păroasă este reliefată, produsă de EBV.","Nu: leziunile violacee conjunctivale țin de sarcomul Kaposi."]],
 [8,"Permutează trei leziuni orale/oculare reale din capitol (afte, candidoză, Kaposi) peste localizarea laterală a leucoplaziei păroase."],["Leucoplazia paroasa","marginile laterale ale limbii"]),

q("hiv-adv-055",["Complicațiile digestive și renale în infecția HIV:",
 ["enteropatie HIV cu atrofie vilozitară de grad variabil","hipoclorhidrie, cu dezvoltare bacteriană intestinală excesivă","sindrom Fanconi asociat tratamentului cu tenofovir","HIVAN predominantă la femeile caucaziene tinere","țesut limfoid rectal fără rol de rezervor viral"],"ABC",1432,"HIV — Enteropatie, hipoclorhidrie și tenofovir/Fanconi",
 "Recunoașterea atrofiei vilozitare, a hipoclorhidriei și a sindromului Fanconi prin tenofovir, distinct de epidemiologia HIVAN.",
 ["Enteropatia HIV cu grade variabile de atrofie a vilozităților este descrisă explicit.","Hipoclorhidria afectează absorbția medicamentelor și favorizează dezvoltarea excesivă a bacteriilor intestinale.","Tenofovirul este asociat cu sindromul Fanconi.","Nu: HIVAN este mai frecventă la bărbații de rasă neagră și poate fi exacerbată de heroină.","Nu: țesutul limfoid rectal este descris ca țintă și rezervor al virusului."]],
 [8,"Inversează profilul HIVAN (rasă, sex, heroină) și neagă rezervorul rectal, ambele pe aceeași pagină."],["sindromul Fanconi","Hipoclorhidria"]),

q("hiv-adv-056",["Pneumopatia interstițială limfoidă (LIP) în infecția HIV:",
 ["descrisă frecvent la copii, dar rară la adulți","infiltrat alveolar limfo-plasmocitar, cu EBV uneori decelat","forma tipică de pneumonie a adultului cu CD4 >500/mm³","etiologie Pneumocystis, cu aspect de sticlă mată","răspuns la co-trimoxazol, EBV nefiind implicat"],"AB",1432,"HIV — Pneumopatia interstițială limfoidă",
 "Recunoașterea LIP ca entitate pediatrică, cu infiltrat limfo-plasmocitar și posibil EBV, rară la adult.",
 ["LIP a fost descrisă frecvent la copiii cu HIV și este rar întâlnită la adulți.","Infiltratul alveolar conține limfocite, plasmocite și limfoblaști, iar virusul Epstein-Barr poate fi decelat.","Nu: LIP nu este pneumonia tipică a adultului cu CD4 păstrat; este descrisă mai ales la copii.","Nu: Pneumocystis și aspectul de sticlă mată țin de PCP, nu de LIP.","Nu: EBV poate fi decelat în LIP, iar textul nu indică co-trimoxazolul ca terapie."]],
 [8,"Confundă LIP-ul pediatric cu PCP-ul adultului (sticlă mată, co-trimoxazol) de pe paginile de infecții oportuniste."],["limfoida {LIP)","Virusul Epstein-Barr"]),

q("hiv-adv-057",["Expresia clinică a imunodepresiei prin HIV:",
 ["depinde de expunere, multe episoade fiind infecții latente reactivate","include TB, Candida și herpes chiar la imunodepresie ușoară","include MAI și Cryptosporidium diseminate la CD4 <100/mm³","justifică profilaxia infecțiilor cu virulență scăzută","debutează cu agenți puțin virulenți, înaintea TB și candidozei"],"ABCD",1433,"HIV — Factorii care modulează expresia clinică",
 "Ierarhizarea expunerii, virulenței (TB/Candida/herpes devreme) și a pragului CD4 <100 pentru MAI/Cryptosporidium, cu indicație de profilaxie.",
 ["Expunerea de-a lungul vieții contează: multe episoade sunt reactivări ale unei infecții latente, iar factorii geografici determină flora.","M. tuberculosis, Candida și virusurile herpetice, fiind virulente, dau manifestări și la imunodepresie ușoară.","La CD4 sub 100/mm³ pot apărea infecții diseminate cu agenți de virulență scăzută, precum MAI și Cryptosporidium.","Pentru infecțiile cu virulență scăzută de acest tip este indicat tratament profilactic.","Nu: microorganismele puțin virulente produc boală tardiv, la imunodepresie severă (CD4 <100/mm³)."]],
 [8,"Inversează calendarul virulenței (precoce versus tardiv) pe fondul pragului CD4<100 real."],["CD4 <100/mm3","Cryptosporidium"]),

q("hiv-adv-058",["Persoana nou diagnosticată cu HIV trebuie evaluată de specialist în:",
 ["șase luni, dacă pacientul este complet asimptomatic","două săptămâni, sau mai rapid dacă are simptome","un an, până la prima determinare a încărcăturii virale","24 de ore, dacă CD4 este sub 50/mm³","trei ani, cât durează latența clinică medie"],"B",1434,"HIV — Evaluarea inițială: intervalul până la specialist",
 "Reținerea ferestrei de două săptămâni (mai rapid dacă simptomatic) pentru evaluarea în serviciul specializat.",
 ["Nu: șase luni depășește intervalul citat, de două săptămâni.","Evaluarea de specialist se face în două săptămâni de la diagnostic, mai rapid dacă pacientul este simptomatic sau are afecțiuni acute.","Nu: un an nu este intervalul din text; evaluarea se face în două săptămâni.","Nu: textul nu condiționează urgența de CD4 <50/mm³; intervalul este de două săptămâni.","Nu: trei ani nu este fereastra evaluării inițiale, care este de două săptămâni."]],
 [8,"Toate intervalele apar în capitol (latență, monitorizare); doar două săptămâni este cel al evaluării inițiale."],["două săptămâni","nou diagnosticati"]),

q("hiv-adv-059",["Genotiparea virală și monitorizarea înaintea ARV:",
 ["genotipare recomandată la diagnostic, pe proba cea mai precoce","identificarea tulpinilor rezistente de novo, care ghidează ARV","monitorizare de 2-4 ori/an în absența ARV","genotipare amânată până după eșecul primei linii","fără vizite până la un eveniment definitoriu SIDA"],"ABC",1434,"HIV — Genotip la diagnostic și monitorizarea pre-ARV",
 "Aplicarea genotipării la nou-diagnosticați (probă precoce) și a ritmului de 2-4 vizite/an la cei care amână ARV.",
 ["Analiza genotipului este recomandată tuturor nou-diagnosticaților, pe proba recoltată cât mai aproape de diagnostic.","Rezultatele ghidează terapia ARV, putând identifica tulpini rezistente de novo.","Pacienții care nu inițiază ARV sunt monitorizați de 2-4 ori pe an, sau mai rar dacă CD4 este crescut.","Nu: genotiparea se face la diagnostic, nu după eșecul primei linii.","Nu: monitorizarea rămâne necesară pentru rata de progresie și opțiunile de tratament."]],
 [8,"Amână genotipul până după eșec, opusul recomandării de probă la diagnostic."],["genotipului viral","2-4 ori pe an"]),

q("hiv-adv-060",["Atazanavirul, inhibitor de protează, se caracterizează prin:",
 ["creșterea bilirubinei neconjugate, cu posibil icter","absența efectelor digestive și lipidice","inhibarea selectivă a integrazei virale, nu a proteazei","administrare fără boosting, ritonavirul fiind contraindicat","lipsa utilizării ca agent de primă linie"],"A",1438,"HIV — Atazanavir: hiperbilirubinemie neconjugată",
 "Recunoașterea icterului prin bilirubină neconjugată ca particularitate a atazanavirului, distinct de mecanismul INSTI.",
 ["Atazanavirul crește nivelul plasmatic al bilirubinei neconjugate și poate produce icter.","Nu: atazanavirul poate produce tulburări gastro-intestinale și ale metabolismului lipidic, ca și darunavirul.","Nu: inhibarea integrazei este mecanismul INSTI, nu al atazanavirului.","Nu: atazanavirul boostat este frecvent folosit ca agent de primă linie.","Nu: atazanavirul boostat este, alături de darunavirul boostat, agent de linia întâi."]],
 [8,"Confundă atazanavirul cu un INSTI și neagă boosting-ul/linia întâi, pe fondul icterului real prin bilirubină neconjugată."],["bilirubinei neconjugate","Atazanavirul"]),

q("hiv-adv-061",["Potențarea (boosting) IP cu doze mici de ritonavir sau cobicistat:",
 ["blochează CYP450, crescând timpul de înjumătățire al IP","crește eficacitatea și reduce riscul de rezistență","crește riscul de tulburări lipidice, în special trigliceride","unii IP au fost asociați cu tulburări de coagulare la hemofilici","scade concentrațiile de IP și crește riscul de rezistență"],"ABCD",1438,"HIV — Boosting-ul inhibitorilor de protează",
 "Echilibrarea câștigului farmacocinetic al boosting-ului (T1/2, pastile, rezistență) cu polipragmazia, interacțiunile, trigliceridele și hemofilia.",
 ["Boosting-ul blochează metabolizarea prin citocromul P450, crescând timpul de înjumătățire și concentrațiile plasmatice, cu mai puține pastile.","Boosting-ul crește eficacitatea și reduce riscul de rezistență.","Dezavantajele includ polipragmazia, alte interacțiuni și riscul crescut de tulburări lipidice, în special trigliceride.","Unii IP au fost asociați cu afectarea coagulării la pacienții cu hemofilie.","Nu: boosting-ul crește concentrațiile de IP și reduce riscul de rezistență."]],
 [8,"Inversează direcția boosting-ului (scade concentrațiile) deși restul listei reproduce avantajele reale din paragraf."],["boosting","trigliceride"]),

q("hiv-adv-062",["Coada subterapeutică după oprirea unui ARV cu timp de înjumătățire lung:",
 ["favorizează apariția tulpinilor rezistente","sterilizează rezervoarele virale latente","este fără consecințe, varianta sălbatică nemaiputând reveni","impune genotiparea la 6 luni după oprire","este un avantaj al INNRT, permițând oprirea bruscă"],"A",1439,"HIV — Rezistență: coada subterapeutică",
 "Recunoașterea „drug tail” de după oprirea unui ARV cu T1/2 lung ca fereastră de selecție a rezistenței.",
 ["Coada subterapeutică după oprirea unui ARV cu timp de înjumătățire lung favorizează apariția tulpinilor rezistente.","Nu: coada subterapeutică nu sterilizează rezervoarele; mutațiile pot fi arhivate.","Nu: coada subterapeutică selectează rezistență; varianta sălbatică redevine dominantă în absența presiunii medicamentoase.","Nu: genotiparea de rezistență se face pe probe recoltate sub tratament.","Nu: INNRT au barieră genetică joasă, iar oprirea lor bruscă nu este un avantaj."]],
 [8,"Transformă coada subterapeutică într-un beneficiu, opusul selecției de rezistență descrise în cadran."],["subtherapeutic drug tail","timp de înjumătăţire lung"]),

q("hiv-adv-063",["Conduita în eșecul virusologic (două viremii >400 copii/ml după supresie):",
 ["investigații suplimentare, inclusiv genotipare","cel puțin doi agenți noi activi","inițierea noului regim cât mai curând posibil","așteptarea scăderii spontane timp de 6 luni","un singur agent nou activ"],"ABC",1440,"HIV — Eșec virusologic: pragul 400 copii/ml",
 "Aplicarea definiției (două viremii >400) și a regulii de cel puțin doi agenți noi activi, inițiați fără întârziere.",
 ["Eșecul virusologic necesită investigații suplimentare, inclusiv genotipare virală.","Noul regim trebuie să conțină cel puțin doi agenți noi la care virusul este sensibil.","Dacă opțiunea adecvată este disponibilă, noul regim se inițiază cât mai curând posibil.","Nu: așteptarea a 6 luni contrazice inițierea cât mai rapidă a noului regim, ghidat de genotipare.","Nu: noul regim trebuie să conțină cel puțin doi agenți noi activi."]],
 [8,"Înlocuiește regula celor doi agenți noi cu expectativă sau reciclară, pe fondul pragului 400 copii/ml ușor de confundat cu 50 sau 200."],["peste 400 copii/ml","cel puţin doi agenţi noi"]),

q("hiv-adv-064",["Metabolismul osos la pacientul cu HIV:",
 ["scăderea DMO la inițierea ARV, mai ales cu tenofovir","FRAX de rutină peste 50 de ani sau la menopauză","tenofovirul DF protejează osul, TAF fiind mai toxic","FRAX se aplică copiilor cu LIP, nu adulților","absența fracturilor de fragilitate raportate"],"AB",1441,"HIV — Densitate osoasă, tenofovir/TAF și FRAX",
 "Corelarea scăderii DMO la inițierea tenofovirului (TAF mai blând) cu FRAX de rutină după 50 de ani/menopauză.",
 ["Scăderea densității osoase s-a observat la inițierea ARV, mai ales cu tenofovir; TAF pare să aibă toxicitate osoasă mai redusă.","Riscul de fractură se evaluează de rutină prin FRAX la toți peste 50 de ani, la femeile la menopauză sau cu alți factori de risc.","Nu: tenofovirul scade densitatea osoasă, iar TAF pare să aibă toxicitate osoasă mai redusă.","Nu: FRAX vizează adulții la risc (peste 50 de ani, menopauză), nu copiii cu LIP.","Nu: la pacienții cu HIV sunt raportate DMO scăzută și fracturi de fragilitate."]],
 [8,"Inversează toxicitatea osoasă TDF versus TAF și mută FRAX pe seama LIP pediatric."],["Tenofovir alafenamida","scorul FRAX"]),

q("hiv-adv-065",["Inițierea ARV în infecția acută și prevenirea IRIS:",
 ["ARV imediat la cei prezentați cu infecție acută","diversitate virală redusă și imunitate încă păstrată","tratamentul TB/criptococozei precede ARV cu circa 4 săptămâni","IRIS apare mai ales la cei cu imunodepresie importantă","în infecția acută, ARV se amână 6 luni de la diagnostic"],"ABCD",1441,"HIV — Infecția acută și fereastra IRIS de 4 săptămâni",
 "Contrastarea inițierii imediate în infecția acută (diversitate redusă) cu amânarea medie de 4 săptămâni în TB/criptococoză pentru IRIS.",
 ["ARV trebuie inițiat imediat la toți cei care se prezintă cu infecție acută HIV.","În infecția acută diversitatea virală este redusă, iar capacitatea imunologică este încă păstrată.","Pentru a evita IRIS în TB și criptococoză, tratamentul specific se dă câteva săptămâni (în medie 4) înaintea ARV.","IRIS apare de obicei la cei cu imunodepresie importantă la inițierea ARV.","Nu: în infecția acută ARV se inițiază imediat, nu se amână 6 luni."]],
 [8,"Importă fereastra de 6 luni a primoinfecției ca interdicție ARV, opusul inițierii imediate din acest paragraf."],["infectie acuta HIV","în medie 4 săptămâni"]),

q("hiv-adv-066",["Prognosticul nefavorabil al meningitei criptococice se asociază cu:",
 ["fungi numeroși, leucocite puține în LCR și conștiență alterată","titrul antigenic care se negativează rapid sub tratamentul antifungic","redoarea de ceafă marcată, prin inflamație viguroasă","absența antigenului criptococic din LCR","hemoculturi negative pentru criptococ"],"A",1444,"HIV — Criptococoză: markeri de prognostic",
 "Reținerea triadei de prognostic nefavorabil (fungi mulți, leucocite puține, conștiență alterată), distinct de antigenul care de obicei nu se negativează.",
 ["Numărul mare de fungi și numărul mic de leucocite în LCR, plus alterarea stării de conștiență la prezentare, indică prognostic nefavorabil.","Nu: titrul scade semnificativ sub tratament, dar de obicei nu se negativează și nu este markerul de prognostic citat.","Nu: redoarea poate lipsi prin răspuns inflamator anormal și nu este factor de prognostic citat.","Nu: antigenul criptococic din LCR poate fi pozitiv, în titruri variabile.","Nu: criptococii pot fi identificați și în hemoculturi; un rezultat negativ nu este criteriul de prognostic."]],
 [8,"Înlocuiește triada de prognostic cu negativarea antigenului, pe care textul o descrie ca rară."],["număr mare de fungi","alterarea stării de constienta"]),

q("hiv-adv-067",["Pneumonia cu Pneumocystis, dincolo de co-trimoxazol:",
 ["atovaquona sau clindamicina cu primachină ca alternative","corticoterapie sistemică în formele severe, scăzând mortalitatea","pentamidina în aerosoli penetrează slab lobii superiori","corticoterapie indicată și în formele ușoare tratate oral","ARV amânat după un an de profilaxie secundară"],"ABC",1444,"HIV — PCP: alternative, steroizi, pneumotorax și pentamidină",
 "Poziționarea atovaquonei/clindamicină-primachinei, a steroizilor în formele severe și a limitelor pentamidinei inhalatorii.",
 ["Atovaquona sau clindamicina plus primachină pot fi alternative la co-trimoxazol.","În cazurile severe corticoterapia sistemică reduce mortalitatea; hipoxia severă poate necesita CPAP sau ventilație, iar evoluția se poate complica cu pneumotorax.","Pentamidina în aerosoli protejează doar plămânii și penetrează ineficient lobii superiori, iar recurențele pot fi atipice sau extrapulmonare.","Nu: în formele ușoare tratate oral corticoterapia nu este indicată.","Nu: ARV trebuie inițiat cât mai precoce la pacienții netratați."]],
 [8,"Extinde steroizii la forma ușoară și amână ARV, opusul textului, pe fondul pneumotoraxului și pentamidinei reale."],["pneumotoraxului","lobilor superiori"]),

q("hiv-adv-068",["Leishmanioza viscerală la pacientul cu HIV:",
 ["splenomegalie, anemie și trombocitopenie importante","amastigote în biopsia medulară sau aspiratul splenic","co-trimoxazol ca tratament de elecție, ca în PCP","serologia ca standard de aur, biopsia fiind superfluă","zone endemice care exclud bazinul mediteranean"],"AB",1445,"HIV — Leishmanioza viscerală",
 "Recunoașterea tabloului spleno-anemic, a vizualizării amastigotelor și a infiabilității serologiei, cu amfotericină liposomală ca tratament.",
 ["Simptomele sunt adesea nespecifice, dar splenomegalia, anemia și trombocitopenia sunt importante.","Amastigotele se vizualizează în biopsia de măduvă sau în aspiratul splenic; serologia nu este fiabilă în acest context.","Nu: tratamentul se face cu amfotericină liposomală, nu cu co-trimoxazol.","Nu: serologia nu este fiabilă în acest context; biopsia medulară sau aspiratul splenic sunt metodele citate.","Nu: zonele endemice includ America de Sud, Africa tropicală și o mare parte din bazinul mediteranean."]],
 [8,"Înlocuiește amfotericina cu co-trimoxazolul PCP și declară serologia standard de aur, opusul infiabilității din text."],["Amastigotele","amfotericina liposomala"]),

q("hiv-adv-069",["Co-infecția HIV/VHC:",
 ["ARV inițiat preferabil cu 4-6 săptămâni înaintea DAA","elastografie cel puțin anuală dacă tratamentul VHC este amânat","DAA în hepatita C acută fără scădere de 2 log10 la 4 săptămâni","reinfecție rară după clearance, prin imunitate protectoare","ARV amânat până la vindecarea VHC, pentru hepatotoxicitate"],"ABC",1446,"HIV — Co-infecția VHC: fereastra 4-6 săptămâni și hepatita C acută",
 "Aplicarea inițierii ARV cu 4-6 săptămâni înaintea DAA, a elastografiei anuale și a regulii de 2 log10 la 4 săptămâni în hepatita C acută.",
 ["Dacă tratamentul VHC este planificat, ARV se inițiază preferabil cu 4-6 săptămâni înaintea DAA.","Cei care temporizează tratamentul VHC trebuie să facă cel puțin anual elastografie hepatică sau altă monitorizare non-invazivă.","Dacă la 4 săptămâni de la diagnosticul hepatitei C acute viremia VHC nu a scăzut cu 2 log10, se încep DAA.","Nu: răspunsul imun nu protejează împotriva reinfecției, iar ratele de reinfecție sunt crescute.","Nu: toți co-infectații trebuie să primească ARV; amânarea ARV până după VHC contrazice recomandarea."]],
 [8,"Neagă reinfecția și inversează ordinea ARV–DAA, două capcane de pe aceeași pagină."],["4-6 săptămâni","elastografie hepatica"]),

q("hiv-adv-070",["La pacientul cu HIV imunodeprimat, HSV genital sau oral produce:",
 ["leziuni veziculoase clasice, cu eliminare virală scurtă","leziuni ulcerative, cu eliminare virală prelungită","leziuni violacee conjunctivale, ca în sarcomul Kaposi","leziuni albicioase reliefate pe marginile limbii","aspect pulmonar de sticlă mată, ca în pneumocistoză"],"B",1447,"HIV — HSV: ulcerativ versus veziculos",
 "Recunoașterea pattern-ului ulcerativ (nu veziculos) și a eliminării virale prelungite a HSV la imunodeprimat.",
 ["Nu: pattern-ul veziculos cu eliminare virală scurtă este al imunocompetentului.","La imunodeprimat leziunile HSV sunt mai degrabă ulcerative decât veziculoase, cu eliminare virală prelungită.","Nu: leziunile violacee conjunctivale sunt ale sarcomului Kaposi.","Nu: zonele albicioase reliefate pe marginile limbii sunt leucoplazia păroasă (EBV).","Nu: aspectul de sticlă mată este al pneumoniei cu Pneumocystis."]],
 [8,"Permutează patru morphologii reale din capitol (vezicule, Kaposi, leucoplazie, sticlă mată) peste HSV-ul ulcerativ."],["ulcerativ decat veziculos","Eliminarea virala a HSV"]),

q("hiv-adv-071",["La pacientul cu HIV, infecțiile cu VZV, EBV și HPV:",
 ["zoster rezistent la aciclovir, care poate răspunde la foscarnet","EBV asociat limfomului cerebral primar și limfoamelor non-Hodgkin","HPV accelerează neoplazia intraepitelială anală și cervicală","justifică recomandarea vaccinării anti-HPV","infecția HPV fără efect asupra neoplaziei cervicale"],"ABCD",1447,"HIV — VZV (foscarnet), EBV oncogen și HPV anogenital",
 "Corelarea zosterului rezistent (timidin-kinază, foscarnet) cu EBV oncogen și cu accelerarea CIN/AIN prin HPV.",
 ["Zosterul este mai agresiv și poate cuprinde mai multe dermatoame; tulpinile rezistente la aciclovir (de obicei mutații de timidin-kinază) pot răspunde la foscarnet.","EBV se asociază frecvent cu limfomul primar cerebral și cu limfoamele non-Hodgkin.","HPV se asociază cu progresia mai rapidă a neoplaziei intraepiteliale anale și cervicale spre carcinom scuamos.","Vaccinarea HPV ar trebui recomandată.","Nu: HPV accelerează progresia neoplaziei intraepiteliale cervicale și anale."]],
 [8,"Restrânge zosterul la CD4<50 (pragul retinitei CMV) și neagă legătura HPV–CIN, ambele de pe pagini vecine."],["timidin-kinaza","foscarnet"]),

q("hiv-adv-072",["Interacțiunile rifamicinelor cu antiretroviralele:",
 ["unii IP cresc nivelul rifamicinelor până la toxicitate, cu uveită","INNRT interacționează cu rifampicina, cu ajustarea dozelor","rifampicina crește concentrația IP până la toxicitate","uveita ca efect al co-trimoxazolului, nu al rifamicinelor","INNRT fără interacțiune semnificativă cu rifampicina"],"AB",1448,"HIV/TB — Rifampicina, uveita și INNRT",
 "Recunoașterea dublei interacțiuni: IP care cresc rifampicina (uveită, hepatotoxicitate) și INNRT care cer ajustare de doză.",
 ["Unii IP blochează citocromul P450 și cresc nivelul rifamicinelor până la toxicitate, cu uveită și efecte hepatotoxice.","INNRT interacționează și ele cu rifampicina, fiind necesară modificarea dozelor.","Nu: rifampicina, prin inducția P450, scade concentrația IP.","Nu: uveita ține de toxicitatea rifamicinelor crescute de unii IP.","Nu: INNRT interacționează cu rifampicina, fiind necesară modificarea dozelor."]],
 [8,"Inversează direcția rifampicină→IP (crește versus scade) și mută uveita pe seama co-trimoxazolului."],["uveita","citocromului P450"]),

q("hiv-adv-073",["Sarcomul Kaposi epidemic (asociat HIV):",
 ["mai agresiv decât forma endemică","tumoră din celule fusiforme, cu fante ce conțin eritrocite","posibilă afectare conjunctivală, cu edem periorbital","formă viscerală cu prognostic mai bun decât cea cutanată","leziuni a căror regresie nu este influențată de ARV"],"ABC",1449,"HIV — Sarcomul Kaposi: histologie și afectare oculară",
 "Corelarea agresivității epidemice, a histologiei (fante cu eritrocite) și a localizării conjunctivale, cu prognosticul mai rezervat al formei viscerale.",
 ["SK epidemic se manifestă mai agresiv decât forma endemică a neinfectaților HIV, iar incidența sa a scăzut după ARV.","Este o tumoră multicentrică din celule fusiforme și endoteliale, cu fante ce captează eritrocite, de unde nuanța violacee.","Poate apărea în jurul ochilor, în special la conjunctivă, cu edem periorbital.","Nu: SK visceral are prognostic mai rezervat decât cel cutanat.","Nu: ARV favorizează regresia leziunilor."]],
 [8,"Inversează prognosticul visceral versus cutanat și neagă regresia sub ARV, două afirmații din același paragraf."],["celule fusiforme","edem periorbital"]),

q("hiv-adv-074",["Circumcizia a redus transmiterea femeie–bărbat cu cel puțin 50%. La partenerele HIV-negative ale bărbaților HIV-pozitivi circumciși, la 2 ani, s-a observat:",
 ["o reducere identică celei de la bărbați, de cel puțin 50%","o reducere mai modestă a incidenței HIV","o creștere a incidenței, prin risc compensator","eliminarea completă a transmiterii, ca în U=U","absența unui efect măsurabil asupra incidenței"],"B",1450,"HIV — Circumcizia: efectul asupra partenerei",
 "Diferențierea reducerii de cel puțin 50% (femeie→bărbat) de reducerea mai modestă a incidenței la partenerele HIV-negative la 2 ani.",
 ["Nu: reducerea de cel puțin 50% privește bărbatul circumcis, nu partenera.","La femeile HIV-negative, la 2 ani de la circumcizia partenerilor HIV-pozitivi, s-a observat o reducere mai modestă a incidenței.","Nu: nu este descrisă o creștere prin risc compensator, ci o reducere mai modestă.","Nu: U=U ține de viremia nedetectabilă sub ARV, nu de circumcizie.","Nu: un efect modest este totuși raportat la partenere."]],
 [8,"Egalizează efectul asupra partenerei cu cei 50% ai bărbatului circumcis, deși textul îl califică mai modest, la 2 ani."],["reducere mai modestă","2 ani de la circumcizia"]),

q("hiv-adv-075",["Controlul HIV, dincolo de PrEP și U=U, este influențat de:",
 ["schimbarea comportamentală, dificilă unde sexualitatea este tabu","stigmatizare, sărăcie, legislație punitivă și războaie","voința politică, care nu este evidentă peste tot","un vaccin deja disponibil, care face inutilă voința politică","notificarea partenerilor, considerată lipsită de controverse"],"ABC",1450,"HIV — Determinanți structurali și voință politică",
 "Recunoașterea obstacolelor tabu/stigmat/sărăcie/legi punitive și a nevoii de voință politică, cu nuanța controverselor notificării partenerilor.",
 ["Înțelegerea și schimbarea comportamentală sunt dificile mai ales unde sexualitatea, HIV și SIDA sunt tabu.","Stigmatizarea, sărăcia, legislația punitivă, inechitatea socială și războaiele pot contribui la răspândire.","Voința politică, care nu este evidentă în toate contextele, este necesară pentru ca progresul să fie susținut.","Nu: dezvoltarea vaccinului este descrisă ca îngreunată; nu există un vaccin care să înlocuiască voința politică.","Nu: notificarea partenerilor este utilă, dar pot apărea controverse."]],
 [8,"Declară vaccinul disponibil și notificarea necontroversată, două afirmații pe care textul le nuanțează opus."],["legislatia punitiva","vointa politica"]),

q("hiv-adv-076",["Impactul global al HIV:",
 ["scăderea cu 38% a cazurilor noi din 2001","principala cauză de invaliditate la 30-45 de ani","principala cauză de deces la femeile de 15-49 de ani","scăderea uniformă a ratei de infecție în Europa de Est","creșterea transmiterii sub ARV eficient"],"ABC",1426,"HIV — Incidență −38% și impact pe grupe de vârstă",
 "Reținerea scăderii de 38% din 2001 și a primatului de invaliditate (30-45 ani) și mortalitate (femei 15-49), versus creșterile din Europa de Est.",
 ["Din 2001, numărul de cazuri noi a scăzut la nivel global cu 38%.","HIV este principala cauză de invaliditate la persoanele de 30-45 de ani.","HIV este principala cauză de deces la femeile de 15-49 de ani.","Nu: rata de infecție continuă să crească în Europa de Est și în părți din Asia Centrală.","Nu: ARV-ul eficient reduce transmiterea."]],
 [8,"Inversează direcția incidenței în Europa de Est și neagă efectul ARV asupra transmiterii, pe fondul a trei cifre reale."],["38%","30 şi 45 de ani"]),

q("hiv-adv-077",["Infecția HIV în Marea Britanie, în 2017:",
 ["101.600 de persoane; 92% diagnosticate, 98% pe ARV, 97% cu supresie","4363 de cazuri noi diagnosticate","o treime peste 50 de ani și 30% femei","sub 10.000 de persoane, fără supresie virală","diagnosticați în majoritate femei sub 25 de ani"],"ABC",1426,"HIV — Marea Britanie 2017: 101.600 și cascada 92/98/97",
 "Trio-ul prevalență 101.600 / 4363 noi / cascada 92-98-97, plus îmbătrânirea (1/3 peste 50) și 30% femei.",
 ["În 2017, 101.600 de persoane trăiau cu HIV; 92% își cunoșteau diagnosticul, 98% dintre aceștia erau pe ARV, iar 97% dintre tratați aveau supresie virală.","În 2017 au fost diagnosticate 4363 de cazuri noi.","O treime dintre cei care trăiesc cu HIV au peste 50 de ani, iar 30% sunt femei.","Nu: în 2017 trăiau cu HIV 101.600 de persoane, iar 97% dintre cei tratați aveau supresie virală.","Nu: 30% dintre persoanele cu HIV sunt femei, iar o treime au peste 50 de ani."]],
 [8,"Subestimează prevalența britanică și anulează cascada 92/98/97, trei ordine de mărime de pe aceeași pagină."],["101.600 de persoane","97% aveau supresie virală"]),

q("hiv-adv-078",["Diagnosticul tardiv și comorbiditățile HIV în Marea Britanie și Europa:",
 ["diagnostic tardiv în scădere de la 52% (2004) la 43% (2017)","75% cu cel puțin încă o afecțiune cronică","internări pentru afecțiuni respiratorii, psihiatrice, cardiovasculare","bolile SIDA au înlocuit afecțiunile netransmisibile unde există ARV","fragilitate apărută abia după 80 de ani, ca la neinfectați"],"ABC",1426,"HIV — Diagnostic tardiv 43% și comorbidități 75%",
 "Perechea 52%→43% CD4 <350 și 75% cu o comorbiditate cronică, plus cauzele de internare europene.",
 ["Diagnosticul tardiv (CD4 <350 în primele 3 luni) a scăzut de la 52% în 2004 la 43% în 2017, dar rămâne ridicat.","75% dintre cei care trăiesc cu HIV au cel puțin încă o afecțiune cronică (sănătate mintală, HTA, lipide, diabet).","În Europa, în 2017, principalele cauze de internare au inclus afecțiuni respiratorii, psihiatrice, cardiovasculare, renale și neurologice.","Nu: unde ARV este accesibil, bolile definitorii SIDA au fost înlocuite de afecțiunile netransmisibile.","Nu: fragilitatea și dizabilitățile apar la persoane mai tinere decât la neinfectați."]],
 [8,"Inversează substituția SIDA→netransmisibile și mută fragilitatea la octogenari, contrar textului despre îmbătrânire precoce."],["43% în 2017","75% dintre cei"]),

q("hiv-adv-079",["Transmiterea verticală a HIV:",
 ["15% fără intervenție, conform studiilor europene","până la 40% în Africa și SUA","risc actual de 1:10 în Marea Britanie","90% din cazurile globale în țări sărace","alăptarea reducea riscul la jumătate în era pre-ARV"],"ABD",1427,"HIV — Transmitere verticală: 15%, 40%, 1:1000, 90%",
 "Ponderile 15% (Europa fără intervenție), până la 40% (Africa/SUA), 1:1000 (Marea Britanie) și 90% din transmiterea verticală în țări sărace.",
 ["Fără intervenție, studiile europene sugerează că 15% dintre nou-născuții din mame HIV-pozitive pot dobândi HIV.","Au fost raportate rate de până la 40% în Africa și SUA.","Nu: în Marea Britanie riscul actual de transmitere verticală este de 1:1000, nu 1:10.","90% din infecțiile materno-fetale globale se înregistrează în țările cu nivel de trai scăzut, prin lipsa accesului la intervenții.","Nu: în era pre-ARV alăptarea dubla riscul de transmitere."]],
 [8,"Inversează efectul alăptării pre-ARV și uită că 90% din MTCT ține de accesul la intervenții."],["15% dintre nou-născuţii","1:1000"]),

q("hiv-adv-080",["Riscul de infectare HIV după o singură înțepătură cu ac contaminat este de aproximativ:",
 ["0,3%","3%","0,03%","1%","30%"],"A",1428,"HIV — Expunere ocupațională: 0,3%",
 "Reținerea riscului de 0,3% per înțepătură, nuanțat de era pre-ARV eficient.",
 ["Riscul după o singură înțepătură cu ac contaminat este de aproximativ 0,3%, date obținute înainte de utilizarea pe scară largă a ARV.","Nu: riscul citat după o singură înțepătură este de aproximativ 0,3%, nu 3%.","Nu: riscul citat este de aproximativ 0,3%, de zece ori mai mare decât 0,03%.","Nu: riscul citat după o singură înțepătură este de aproximativ 0,3%.","Nu: 30% este ordinul transmiterii verticale fără intervenție, nu al înțepăturii."]],
 [8,"Permutează 0,3% (înțepătură) cu 15-40% (vertical) sau 50% (circumcizie), toate din capitolul de transmitere."],["0,3%","înţepături cu un ac"]),

q("hiv-adv-081",["HIV-2 și grupurile HIV-1:",
 ["HIV-2: 40% omologie cu HIV-1, evoluție mai lentă","multe ARV anti-HIV-1 ineficiente pe HIV-2","grupul M: 98% din infecții, subtip B în Europa, C în Africa","HIV-2 identic structural cu HIV-1, cu aceleași ARV","grupul M sub 5% din infecțiile globale"],"ABC",1428,"HIV — HIV-2 (40% omologie) și grupul M 98%",
 "Omologia de 40%, ineficiența multor ARV, ponderea de 98% a grupului M și clivajul subtip B versus C.",
 ["HIV-2 este limitat aproape în întregime la Africa de Vest (și Europa), are doar 40% omologie structurală cu HIV-1 și evoluție mai lentă.","Multe ARV folosite în HIV-1 sunt ineficiente în HIV-2.","Grupul M reprezintă 98% din infecțiile globale; subtipul B predomină în Europa/America de Nord/Australia, subtipul C în Africa Centrală și subsahariană.","Nu: HIV-2 are doar 40% omologie structurală cu HIV-1, iar multe ARV sunt ineficiente pe HIV-2.","Nu: grupul M reprezintă 98% din infecții, iar subtipul B predomină în Europa."]],
 [8,"Atribuie HIV-2 același spectru ARV și inversează 98% (grup M) cu o pondere marginală."],["40% omologie structurală","98% din infecţiile"]),

q("hiv-adv-082",["Turnover-ul viral și răspunsul umoral precoce în HIV:",
 ["timpul de înjumătățire al virusului circulant de circa 6 zile","10⁸-10⁹ particule eliberate și eliminate zilnic","anticorpi neutralizanți la circa 12 săptămâni de la infecție","producție virală celulară de 2 săptămâni, fără moarte celulară","anticorpi neutralizanți prezenți din prima zi de infecție"],"BC",1429,"HIV — T1/2 6 ore, 10⁸-10⁹ particule/zi, Ac la 12 săptămâni",
 "Cinetica virală: T1/2 de 6 ore, 10⁸-10⁹ particule zilnic, 2 zile de producție celulară și fereastra de 12 săptămâni a anticorpilor neutralizanți.",
 ["Nu: timpul de înjumătățire al virusului în circulație este de aproximativ 6 ore.","Pentru nivelurile de viremie observate, zilnic trebuie eliberate și eliminate 10⁸-10⁹ particule.","Anticorpii neutralizanți apar la aproximativ 12 săptămâni de la infecție.","Nu: producția de virus de către celula infectată durează aproximativ 2 zile, fiind limitată de moartea celulei.","Nu: anticorpii neutralizanți apar la aproximativ 12 săptămâni, nu din prima zi."]],
 [8,"Umflă producția celulară de la 2 zile la 2 săptămâni și anulează fereastra de 12 săptămâni a Ac."],["6 ore","12 săptămâni de la infecţie"]),

q("hiv-adv-083",["Primoinfecția HIV se caracterizează prin:",
 ["2-4 săptămâni silențioase, apoi posibilă boală autolimitată","seroconversie în prima oră, fără fereastră silențioasă","boală acută cu durata de 12 luni, fără recuperare","creștere marcată a CD4, raportul CD4:CD8 rămânând normal","ARN-HIV plasmatic absent, cu antigen p24 încă nedetectabil"],"A",1430,"HIV — Infecția acută: 2-4 săptămâni silențioase, 3-6 săptămâni boală",
 "Calendarul 2-4 săptămâni silențioase, 3-6 săptămâni debut, durată până la 3 săptămâni, versus markerii p24/ARN prezenți.",
 ["Primele 2-4 săptămâni pot fi silențioase clinic și serologic; după 3-6 săptămâni poate apărea o boală virală autolimitată, de până la 3 săptămâni, confundabilă cu mononucleoza.","Nu: există o fereastră silențioasă clinic și serologic de 2-4 săptămâni.","Nu: boala acută durează până la 3 săptămâni, cu recuperare de obicei completă.","Nu: CD4 pot fi scăzute, iar raportul CD4:CD8 poate fi inversat.","Nu: ARN-ul viral plasmatic este crescut, iar p24 poate fi detectat."]],
 [8,"Comprimă fereastra silențioasă la o oră și inversează CD4/ARN, calendarul clasic al primoinfecției."],["2-4 săptămâni","3-6 săptămâni"]),

q("hiv-adv-084",["NAAT, setpoint-ul viral și elite controllers:",
 ["NAAT pozitiv cu 7 zile înaintea p24 și 12 înaintea anticorpilor","elite controllers cu viremie <2000 copii/ml fără ARV","setpoint stabilit la circa 6 luni de la seroconversie","NAAT pozitiv la 7 zile după p24, anticorpii precedând ARN","elite controllers cu viremie persistentă >100.000 copii/ml"],"ABC",1430,"HIV — NAAT −7/−12 zile, elite <2000, setpoint 6 luni",
 "Fereastra NAAT (7 și 12 zile), pragul elite <2000 și setpoint-ul de la 6 luni cu gradientul prognostic 100.000 versus 10.000.",
 ["NAAT pentru ARN-HIV poate diagnostica infecția cu 7 zile înaintea antigenului p24 și cu 12 zile înaintea unui test de anticorpi cu sensibilitate crescută.","Elite controllers, subgrup al long-term non-progressors, mențin fără ARV viremie sub 2000 copii/ml sau nedetectabilă.","La aproximativ 6 luni de la seroconversie se stabilește un setpoint viral; >100.000 copii/ml înseamnă risc de 10 ori mai mare de SIDA în 5 ani față de <10.000.","Nu: NAAT precede atât p24 (cu 7 zile), cât și anticorpii (cu 12 zile).","Nu: elite controllers au viremie sub 2000 copii/ml sau nedetectabilă."]],
 [8,"Inversează ordinea NAAT–p24–Ac și confundă elite-ii cu viremia de prognostic nefavorabil."],["7 zile înaintea","2.000 copii/ml"]),

q("hiv-adv-085",["Complicațiile renale și cardiovasculare ale HIV:",
 ["HIVAN, mai frecventă la bărbații de rasă neagră","risc cardiovascular dublu și HDL mai mic la netratați","HIVAN ca nefropatie diabetică tipică la femei caucaziene","risc cardiovascular înjumătățit, cu HDL crescut","absența toxicității renale a tenofovirului"],"AB",1432,"HIV — HIVAN (FSGS, rasă neagră) și risc CV dublu",
 "Profilul HIVAN (bărbat de rasă neagră, heroină, GSFS) și dublarea riscului CV cu HDL scăzut la netratați.",
 ["HIVAN este mai frecventă la bărbații de rasă neagră, poate fi exacerbată de heroină și este o glomeruloscleroză focală segmentară cu tubulopatie.","Pacienții cu HIV au risc de două ori mai mare de afecțiuni cardiovasculare, iar HDL-ul netrataților este mai mic decât la neinfectați.","Nu: HIVAN nu predomină la femeile caucaziene și este o glomeruloscleroză focală segmentară, nu o nefropatie diabetică.","Nu: riscul cardiovascular este dublu, iar HDL-ul netrataților este mai mic.","Nu: tenofovirul este asociat cu sindromul Fanconi."]],
 [8,"Inversează terenul HIVAN și direcția riscului CV/HDL, două paragrafe consecutive de complicații de organ."],["rasă neagră","de două ori mai mare"]),

q("hiv-adv-086",["Cel mai sensibil test de ARN-HIV citat detectează până la:",
 ["20 de copii/ml","2000 de copii/ml","100.000 de copii/ml","200 de copii/ml","50 de copii/ml"],"A",1434,"HIV — Sensibilitatea viremiei: 20 copii/ml",
 "Pragul analitic de 20 copii/ml, distinct de 2000 (elite) și 100.000 (prognostic).",
 ["Cel mai sensibil test citat detectează până la 20 de copii de ARN viral/ml.","Nu: 2000 copii/ml este pragul elite controllers, nu limita de detecție.","Nu: 100.000 copii/ml este pragul de prognostic al setpoint-ului, nu limita de detecție.","Nu: cel mai sensibil test detectează până la 20 de copii/ml, nu 200.","Nu: limita citată a celui mai sensibil test este de 20 de copii/ml."]],
 [8,"Permutează 20 (limită analitică), 2000 (elite) și 100.000 (setpoint), trei praguri de viremie."],["20 copii","ARN viral/ ml"]),

q("hiv-adv-087",["Monitorizarea viremiei și a CD4 sub ARV:",
 ["scăderea viremiei începe la 4 săptămâni, maximă la 10-12","viremie nedozată în prima lună după vaccinare","CD4 anual după stabilizare și CD4 >350/mm³","viremia dozată la o săptămână după vaccinarea antigripală","oprirea monitorizării CD4 după prima lună de ARV"],"ABC",1434,"HIV — Cinetica VL 4/10-12 săptămâni și fereastra post-vaccin",
 "Calendarul 4 apoi 10-12 săptămâni, interdicția de a doza viremia la <1 lună după vaccin/infecție și ritmul anual al CD4 peste 350.",
 ["Încărcătura virală începe să scadă la 4 săptămâni și atinge scăderea maximă în săptămânile 10-12.","Imunizările (gripă, pneumococ) și infecțiile intercurente pot crește tranzitoriu viremia, care nu se evaluează la mai puțin de o lună de la acestea.","După stabilizare virusologică și CD4 >350/mm³ sub ARV, CD4 se monitorizează aproximativ o dată pe an.","Nu: vaccinarea poate crește tranzitoriu viremia, care nu se dozează la mai puțin de o lună după aceasta.","Nu: după stabilizare CD4 se monitorizează anual, nu se oprește după o lună."]],
 [8,"Dozează viremia în ziua vaccinului — tocmai artefactul pe care textul îl evită prin fereastra de o lună."],["4 săptămâni","săptămânile 10-12"]),

q("hiv-adv-088",["Particularități de clasă ale ARV (Cadranul 37.16):",
 ["abacavir: hipersensibilitate asociată HLA-B*5701","nevirapină: hepatotoxicitate mai frecventă la CD4 sub 250 la femei","maraviroc: ineficient în prezența tropismului CXCR4","enfuvirtide: subcutanat de două ori pe zi, ca ultimă linie","rilpivirină utilizabilă indiferent de viremia inițială"],"ACD",1436,"ARV — HLA-B*5701, nevirapină/CD4, maraviroc, enfuvirtide",
 "Constrângeri de clasă: HLA-B*5701, pragurile CD4 ale nevirapinei (250 femei, 400 bărbați), tropismul CCR5 și enfuvirtide s.c. ×2.",
 ["Abacavirul se asociază cu hipersensibilitate la purtătorii HLA-B*5701; abacavir+lamivudină se folosește numai dacă viremia inițială este <100.000 copii/ml.","Nu: riscul de hepatotoxicitate severă crește la CD4 peste 250/mm³ la femei și peste 400/mm³ la bărbați.","Maraviroc este eficient numai în absența tropismului CXCR4 și se leagă de celula gazdă, nu de ținta virală.","Enfuvirtide se administrează subcutanat de două ori pe zi, la pacienții fără alte opțiuni.","Nu: rilpivirina se folosește numai dacă viremia inițială este <100.000 copii/ml."]],
 [8,"Anulează pragurile <100.000 și CD4 ale nevirapinei, patru note de subsol din același cadran de clase."],["HlA-8*5701",">250 celule/mm3 la femei"]),

q("hiv-adv-089",["Rezistența la ARV și interacțiunile:",
 ["o singură mutație poate da rezistență înaltă la INNRT","rezistență transmisă de 2-20% în infecția primară","sunătoarea și rifampicina scad nivelurile unor ARV","barieră genetică înaltă a INNRT, o mutație fiind insuficientă","genotipare de rezistență după oprirea ARV"],"ABC",1439,"Rezistență — INNRT o mutație, 2-20% primar, sunătoare",
 "Bariera genetică joasă a INNRT, intervalele 2-20% / 3-10% și inductorii (sunătoare, rifampicină), plus antiacidele pentru INSTI.",
 ["În clasa INNRT, o singură mutație punctiformă poate da rezistență înaltă, pe când INRT și IP cer acumularea mai multor mutații.","Prevalența rezistenței transmise în infecția primară este de 2-20%; la cronicii netratați, mutațiile primare sunt de 3-10%.","Sunătoarea și rifampicina induc P450 și pot scădea nivelurile unor ARV; INSTI pot fi reduși de antiacide.","Nu: INNRT au barieră genetică joasă, o singură mutație putând da rezistență înaltă.","Nu: genotiparea la eșec se face sub ARV, altfel revine tulpina sălbatică."]],
 [8,"Inversează bariera INNRT și cere genotiparea după oprire, două capcane din Cadranul 37.20."],["2 şi 20%","3 şi 10%"]),

q("hiv-adv-090",["Gravida cu HIV și nou-născutul:",
 ["transmitere 0,1% în UK cu ARV și viremie <50 copii/ml","zidovudină sirop la nou-născut timp de 4 luni","ARV pentru făt din trimestrul II dacă viremia >30.000 copii/ml","alăptare recomandată, riscul fiind de 40% sub ARV","zidovudina neonatală omisă dacă mama are viremie >100.000"],"AC",1441,"Sarcina — Transmitere 1%/0,1%, AZT 4 săptămâni, praguri 30.000/100.000",
 "Perechea 1% versus 0,1% (VL <50), siropul de zidovudină 4 săptămâni și pragurile 30.000/100.000 pentru inițierea ARV în sarcină.",
 ["În Marea Britanie transmiterea este de 1% la femeile diagnosticate antenatal și de 0,1% dacă sunt pe ARV cu viremie <50 copii/ml.","Nu: nou-născutul primește zidovudină sirop timp de 4 săptămâni.","Dacă mama refuză ARV pentru propria sănătate, inițierea pentru făt se face la începutul trimestrului II dacă VL >30.000 copii/ml, sau mai devreme dacă >100.000.","Nu: mamele sunt sfătuite să nu alăpteze, deși riscul sub ARV eficient este extrem de scăzut.","Nu: zidovudina neonatală se administrează 4 săptămâni și nu se omite la viremie maternă înaltă."]],
 [8,"Inversează pragurile 30.000/100.000 și impune alăptarea, contrar paragrafului de obstetrică britanică."],["0,1%","30.000 de copii/ml"]),

q("hiv-adv-091",["Tratamentul meningitei criptococice la pacientul cu HIV:",
 ["amfotericină B liposomală 4,0 mg/kg/zi, cu sau fără flucitozină","fluconazol după 2 săptămâni i.v., până la 8 săptămâni","ARV inițiat la aproximativ 4 săptămâni, pentru a reduce IRIS","corticoterapie de primă linie, cu evitarea amfotericinei","ARV în aceeași zi cu amfotericina, fără întreținere"],"ABC",1444,"Criptococ — Amfotericină 4 mg/kg, fluconazol 8 săptămâni, ARV la 4 săptămâni",
 "Doza de 4,0 mg/kg, secvența 2 apoi 8 săptămâni și fereastra ARV de ~4 săptămâni, cu întreținere până la CD4 >100 timp de un an.",
 ["Tratamentul inițial este amfotericina B liposomală 4,0 mg/kg/zi i.v., cu sau fără flucitozină.","După 2 săptămâni de tratament i.v. se continuă cu fluconazol până la 8 săptămâni.","ARV se inițiază la aproximativ 4 săptămâni pentru a reduce IRIS; întreținerea cu fluconazol continuă până la 1 an, VL nedetectabilă și CD4 constant >100/mm³.","Nu: corticoterapia nu este recomandată; amfotericina B liposomală este tratamentul inițial.","Nu: ARV-ul precoce crește riscul de IRIS, iar întreținerea cu fluconazol este necesară."]],
 [8,"Pornește ARV în ziua 0 și adaugă steroizi, tocmai ce textul evită în criptococoză."],["4,0 mg/kg/zi","peste 100/mm3"]),

q("hiv-adv-092",["Profilaxia pneumoniei cu Pneumocystis:",
 ["la CD4 <200/mm³: co-trimoxazol 960 mg ×3/săptămână","pentamidina în aerosoli penetrează slab lobii superiori","pentamidina inhalatorie protejează și extrapulmonar","fluconazol de elecție, C. krusei fiind sensibilă","atovaquona în locul CPAP-ului în hipoxia severă"],"AB",1444,"PCP — Co-trimoxazol 960 mg ×3/săptămână și limitele pentamidinei",
 "Pragul CD4 <200, doza de 960 mg de 3 ori/săptămână și eșecul pentamidinei pe lobii superiori/extrapulmonar.",
 ["Profilaxia este indicată la CD4 sub 200/mm³; standardul este co-trimoxazol 960 mg de trei ori pe săptămână.","Pentamidina în aerosoli protejează doar plămânii și penetrează slab lobii superiori; recurențele pot fi atipice sau extrapulmonare.","Nu: pentamidina în aerosoli protejează doar plămânii, iar recurențele pot fi extrapulmonare.","Nu: C. krusei este rezistentă la fluconazol, iar fluconazolul nu are rol în PCP.","Nu: hipoxia severă necesită CPAP sau ventilație, nu înlocuirea lor cu atovaquonă."]],
 [8,"Extinde pentamidina la extrapulmonar și mută C. krusei în PCP, două confuzii de pe aceeași pagină de OI fungice."],["960 mg","Pentamidina"]),

q("hiv-adv-093",["Tratamentul de elecție al aspergilozei la pacientul cu HIV:",
 ["voriconazol, cu amfotericină B liposomală ca alternativă","co-trimoxazol 960 mg de trei ori pe săptămână","fluconazol, la care C. krusei este sensibilă","pirimetamină cu doză de încărcare","caspofungină de primă intenție, voriconazol ca alternativă"],"A",1444,"HIV — Aspergiloza: voriconazol",
 "Voriconazolul ca elecție, cu amfotericină 3 mg/kg sau caspofungină ca alternative, nu schemele de PCP/Candida/toxoplasmoză.",
 ["Voriconazolul este tratamentul de elecție; alternative sunt amfotericina B liposomală 3 mg/kg i.v. zilnic sau caspofungina.","Nu: co-trimoxazolul 960 mg de trei ori pe săptămână este profilaxia PCP.","Nu: fluconazolul nu este elecția, iar C. krusei este rezistentă la fluconazol.","Nu: pirimetamina ține de tratamentul toxoplasmozei.","Nu: voriconazolul este elecția, iar caspofungina este una dintre alternative."]],
 [8,"Înlocuiește voriconazolul cu co-trimoxazol, fluconazol sau pirimetamină, trei OI de pe aceeași pagină."],["voriconazol","3 mg/kg i.v."]),

q("hiv-adv-094",["Retinita CMV la pacientul cu HIV:",
 ["apare la CD4 <50/mm³, cu aspect de „felie de pizza”","valganciclovir oral 900 mg de două ori pe zi","ganciclovir mielosupresiv, foscarnet nefrotoxic","apariție tipică la CD4 >500/mm³","valganciclovir de întreținere superior ganciclovirului intravenos"],"ABC",1446,"CMV — Retinită CD4<50, felie de pizza, valganciclovir 900×2",
 "Pragul CD4 <50, dozele 900/5/90 și toxicitățile ganciclovir versus foscarnet.",
 ["Retinita CMV poate apărea la CD4 <50/mm³, are aspect de „felie de pizza” (hemoragii și exsudate perivasculare) și netratată distruge retina.","Tratamentul se începe cât mai curând: valganciclovir 900 mg ×2/zi oral, ganciclovir 5 mg/kg ×2/zi sau foscarnet 90 mg/kg ×2/zi i.v., cel puțin 3 săptămâni.","Ganciclovirul poate produce mielosupresie, iar foscarnetul este nefrotoxic.","Nu: boala CMV apare la CD4 constant <100/mm³, retinita la <50/mm³, iar netratată distruge retina.","Nu: valganciclovirul oral de întreținere are eficacitate mai scăzută decât ganciclovirul i.v."]],
 [8,"Mută retinita la CD4>500 și inversează ierarhia valganciclovir versus ganciclovir i.v."],["900 mg x 2/zi","felie de pizza"]),

q("hiv-adv-095",["Colita și poliradiculopatia CMV:",
 ["colita: incluziuni „ochi de bufniță”, ganciclovir 14-28 de zile","poliradiculopatie cu LCR predominant neutrofilic","colita tratată cu fluconazol, fără incluziuni","LCR acelular în poliradiculopatia lombo-sacrată","întreținere necesară chiar după reconstituirea imună"],"AB",1446,"CMV — Ochi de bufniță și LCR neutrofilic în poliradiculopatie",
 "Perechea histologică „ochi de bufniță” + 14-28 de zile de ganciclovir și LCR-ul neutrofilic al poliradiculopatiei.",
 ["Colita CMV prezintă histologic incluziuni „ochi de bufniță” și se tratează cu ganciclovir 5 mg/kg ×2/zi i.v. timp de 14-28 de zile.","În poliradiculopatia lombo-sacrată CMV, leucocitele din LCR sunt aproape în totalitate neutrofile.","Nu: fluconazolul nu tratează colita CMV, care prezintă incluziuni „ochi de bufniță”.","Nu: LCR-ul din poliradiculopatie conține leucocite aproape în totalitate neutrofile.","Nu: întreținerea nu mai este necesară după ameliorarea imună prin ARV."]],
 [8,"Înlocuiește ganciclovirul cu fluconazol și neagă neutrofilele din LCR, două detalii CMV de pe aceeași pagină."],["ochi de bufniţă","14-28 de zile"]),

q("hiv-adv-096",["Leucoencefalopatia multifocală progresivă (virus JC):",
 ["infecția oligodendrocitelor, cu leziuni ale substanței albe","diagnostic prin PCR JC în LCR și RMN, fără biopsie","lipsa tratamentului specific, ARV eficient putând da remisie","leziuni care captează contrast, cu efect de masă important","vindecare prin ganciclovir intravenos, fără nevoie de ARV"],"ABC",1447,"PML — JC, T2 fără contrast/masă, doar ARV",
 "Profilul imagistic (fără contrast, fără efect de masă) și absența terapiei specifice în afara ARV.",
 ["Virusul JC infectează oligodendrocitele; leziunile sunt de obicei multiple, limitate la substanța albă, fără captare de contrast și fără efect de masă.","RMN arată hipersemnal T2; PCR JC în LCR plus imagistica sunt de regulă suficiente, biopsia nemaifiind necesară.","Terapia specifică lipsește; ARV-ul eficient este singura intervenție care poate da remisie clinică și radiologică.","Nu: leziunile PML nu captează contrast și nu au efect de masă, spre deosebire de abcesul toxoplasmic.","Nu: nu există tratament specific anti-JC; ganciclovirul ține de CMV, iar ARV-ul este singura intervenție eficientă."]],
 [8,"Atribuie PML-ului inelul și masa toxoplasmei și înlocuiește ARV-ul cu ganciclovir, două OI cerebrale vecine."],["nu captează","virusului JC"]),

q("hiv-adv-097",["Tuberculoza la pacientul cu HIV:",
 ["tablou similar celui fără HIV la imunitate relativ bună","forme atipice, adesea extrapulmonare, în stadii avansate","spută posibil negativă la microscopie, culturile fiind optime","IDR la tuberculină interpretabilă indiferent de CD4","durată mai scurtă a tratamentului formelor extrapulmonare"],"ABC",1447,"TB-HIV — Tablou similar versus extrapulmonar atipic",
 "Gradientul imun: tablou similar HIV-negativ versus extrapulmonar/bacteriemie, plus sputa negativă și culturile.",
 ["La un status imunologic relativ bun, tabloul TB este similar celui de la pacientul fără HIV.","În stadiile avansate manifestările sunt atipice, adesea extrapulmonare (ganglioni, măduvă, ficat), cu posibilă bacteriemie.","Examenul microscopic al sputei poate fi negativ chiar în infecția pulmonară; culturile sunt cel mai bun instrument.","Nu: IDR la tuberculină poate fi neinterpretabilă la imunodepresie severă.","Nu: durata tratamentului poate fi mai lungă, mai ales în formele extrapulmonare."]],
 [8,"Face IDR-ul infailibil și scurtează extrapulmonarul, inversând nuanțele de diagnostic TB-HIV."],["extrapulmonară","culturile reprezintă"]),

q("hiv-adv-098",["Testarea HIV în Marea Britanie (date din 2017):",
 ["circa 8% dintre persoanele cu HIV erau nediagnosticate","43% dintre nou-diagnosticați aveau CD4 <350/mm³","23% aveau CD4 <200/mm³ la diagnostic","testare în urgențe la seroprevalență peste 2/1000","circa 23% dintre persoanele cu HIV erau nediagnosticate"],"ABCD",1449,"Prevenție — 8% nediagnosticați, 23% CD4<200, prag 2/1000",
 "Trio-ul 8% / 43% / 23% și pragul de seroprevalență 2/1000 pentru testarea în urgență/asistența primară.",
 ["În 2017, aproximativ 8% dintre pacienții cu HIV din Marea Britanie erau nediagnosticați.","43% dintre nou-diagnosticați au fost diagnosticați tardiv (CD4 <350/mm³).","23% dintre nou-diagnosticați au avut CD4 <200/mm³ la diagnostic.","Testarea se recomandă noilor înregistrați în asistența primară și în urgențe unde seroprevalența depășește 2/1000.","Nu: aproximativ 8% erau nediagnosticați; 23% este proporția celor cu CD4 <200/mm³ la diagnostic."]],
 [8,"Anulează 8% și 23% în favoarea unui screening inutil, trei procente din același bilanț 2017."],["8% din pacienţii","2/1.000"]),

q("hiv-adv-099",["Testele HIV la domiciliu sau point-of-care:",
 ["impun confirmare serologică din cauza fals-pozitivelor","înlocuiesc serologia, fals-pozitivele fiind absente","se interpretează din salivă, fără confirmare","sunt interzise legislativ în Marea Britanie","înlocuiesc evaluarea specialistului dacă sunt pozitive"],"A",1449,"Testare — Fals-pozitive la domiciliu și confirmare serologică",
 "Obligația confirmării serologice după un test reactiv la domiciliu/point-of-care, din cauza fals-pozitivelor.",
 ["Din cauza unei rate semnificative de rezultate fals pozitive, testele reactive trebuie urmate de serologie de confirmare și programare rapidă la specialist.","Nu: nu înlocuiesc serologia, având o rată semnificativă de fals-pozitive.","Nu: există teste din sânge sau din salivă, iar confirmarea serologică rămâne necesară.","Nu: modificările legislative au permis vânzarea truselor de testare.","Nu: evaluarea specialistului rămâne necesară dacă infecția este confirmată."]],
 [8,"Tratează testul de domiciliu ca diagnostic definitiv, tocmai capcana fals-pozitivului semnalată în text."],["fals pozitive","point-of-care"]),

q("hiv-adv-100",["PrEP și mesajul U=U:",
 ["profilaxia PrEP cu TDF-FTC reduce riscul cu până la 90%","transmisie zero în studiile Partner la viremie nedetectabilă","U=U susține beneficiile testării și ale ARV","eficacitate PrEP sub 10%, cu evitare la heterosexuali","transmisie de 50% în studiile Partner"],"ABC",1450,"Prevenție — PrEP TDF-FTC până la 90% și U=U",
 "Reducerea de până la 90% prin PrEP și transmisia zero din studiile Partner, distinse de 50% al circumciziei.",
 ["PrEP orală cu tenofovir-emtricitabină, zilnic sau înainte de expunere, reduce riscul cu până la 90% dacă este luată constant.","Studiile Partner 1 și 2 au raportat transmisie zero de la partenerul pe ARV cu viremie nedetectabilă.","Mesajul U=U (nedetectabil = netransmisibil) evidențiază beneficiile testării și ale ARV.","Nu: PrEP reduce riscul cu până la 90%, atât la BSB, cât și la heterosexuali.","Nu: studiile Partner au raportat transmisie zero; 50% este reducerea prin circumcizie."]],
 [8,"Permutează 90% (PrEP) cu 50% (circumcizie) și neagă transmisia zero U=U."],["până la 90%","nedetectabil = netransmisibil"]),

q("hiv-adv-101",["Nu există dovezi că HIV se transmite prin:",
 ["contact social, domestic sau prin țânțari și tăuni","acele contaminate ale consumatorilor de droguri injectabile","sânge netestat și factori de coagulare înainte de 1985","transmitere perinatală și prin alăptare","contact heterosexual în Africa subsahariană"],"A",1428,"HIV — Absența transmiterii sociale și vectoriale",
 "Negarea explicită a contactului social/domestic și a vectorilor hematofagi, versus căile reale de transmitere.",
 ["Textul neagă transmiterea prin contact social sau domestic ori prin insecte hematofage, precum țânțarii și tăunii.","Nu: acele contaminate ale consumatorilor de droguri i.v. sunt o cale principală de transmitere.","Nu: transmiterea prin sânge netestat și factori de coagulare înainte de 1985 este recunoscută.","Nu: transmiterea perinatală și prin alăptare este o cale reală.","Nu: contactul heterosexual predomină ca mod de transmitere în Africa subsahariană."]],
 [8,"Singura cale pe care textul o neagă (social/insecte) versus patru căi afirmate pe aceleași pagini de transmitere."],["ţânţarii şi tăunii","contact social sau domestic"]),

q("hiv-adv-102",["Pătrunderea și replicarea HIV în limfocitul T CD4:",
 ["gp120 leagă CD4 și co-receptorii CCR5 sau CXCR4","ADN-ul revers-transcris se integrează în genomul gazdei","p24 este proteina de capsidă, p17 proteina-matrice","fuziunea cu membrana independentă de gp41","replicare fără revers-transcriptază sau integrare"],"ABC",1428,"HIV — gp120/CCR5/CXCR4, gp41, p24/p17",
 "Cuplarea gp120–CD4–CCR5/CXCR4, fuziunea prin gp41 și markerii p24/p17.",
 ["gp120 se leagă de CD4 și de co-receptorii CCR5 sau CXCR4, iar gp41 mediază fuziunea cu membrana.","Revers-transcrierea produce ADN din ARN, iar ADN-ul se integrează în genomul gazdei.","p24 (proteina de capsidă) poate fi folosit pentru monitorizarea infecției; p17 este proteina-matrice.","Nu: fuziunea cu membrana celulei gazdă este mediată de gp41.","Nu: revers-transcriptaza și integrarea în genomul gazdei definesc replicarea retrovirusului."]],
 [8,"Anulează CD4/gp41 și RT, adică tocmai schema din Fig. 37.10-37.11."],["CCR5 şi CXCR4","gp41"]),

q("hiv-adv-103",["Profilaxia post-expunere (PEP) la HIV:",
 ["indicată după expunere ocupațională sau sexuală","triplă terapie susținută de studii pe animale","înlocuiește PrEP-ul zilnic la BSB, fără evaluarea riscului","administrată la 6 luni după expunere","triplă terapie contraindicată, rezervată primoinfecției"],"AB",1441,"PEP — Ocupațională și sexuală, triplă terapie fără studiu prospectiv",
 "Indicația dublă (ocupațional + sexual) și absența studiilor prospective, cu tripla terapie susținută de modele animale.",
 ["Personalul cu expunere ocupațională și persoanele expuse sexual trebuie să primească PEP.","Studiile pe animale susțin tripla terapie ca PEP, dar nu există studii prospective care să arate cea mai bună opțiune; fiecare situație se evaluează individual.","Nu: fiecare situație se evaluează individual, iar PEP nu înlocuiește PrEP-ul ca strategie populațională.","Nu: PEP se administrează imediat după expunere, nu la 6 luni.","Nu: tripla terapie este tocmai opțiunea susținută de studiile pe animale."]],
 [8,"Amână PEP-ul 6 luni și îl confundă cu PrEP/primoinfecția, trei ferestre distincte din capitol."],["Profilaxia post-expunere","triplei terapii"]),

q("hiv-adv-104",["Hepatita C acută la pacientul cu HIV:",
 ["DAA dacă viremia VHC nu scade cu 2 log10 în 4 săptămâni","recădere tratată ca VHC cronică, reinfecție ca VHC acută","ARV amânat la 12 luni după terminarea DAA","clearance spontan cu imunitate sterilizantă protectoare","DAA evitate la co-infectați, rezervate monoinfecției"],"AB",1446,"HIV/VHC acut — 2 log la 4 săptămâni și reinfecție versus recădere",
 "Regula 2 log10 la 4 săptămâni și distincția recădere (cronic) versus reinfecție (acut).",
 ["Ghidurile UK: dacă la 4 săptămâni de la diagnosticul infecției acute viremia VHC nu scade cu 2 log10, se începe DAA.","Răspunsul imun nu protejează de reinfecție; recăderea se tratează ca VHC cronică, iar reinfecția ca hepatită C acută.","Nu: ARV se inițiază de preferință cu 4-6 săptămâni înaintea DAA, iar elastografia anuală este necesară dacă se temporizează tratamentul VHC.","Nu: răspunsul imun nu protejează de reinfecție, raportată după clearance spontan sau terapeutic.","Nu: opțiunile DAA sunt similare celor din monoinfecție, cu aviz de expert pentru interacțiuni."]],
 [8,"Transformă absența imunității post-VHC în protecție sterilizantă și amână ARV-ul un an."],["4 săptămâni","reinfecţiei"]),

q("hiv-adv-105",["Neoplaziile asociate HIV:",
 ["SK visceral, cu prognostic mai rezervat decât cel cutanat","NHL cu celulă mare B, frecvent extraganglionar, asociat EBV","citologie cervicală anuală recomandată femeilor cu HIV","SK cutanat cu prognostic mai grav decât cel visceral","limfoame indolente, fără simptome B, EBV-negative"],"ABC",1449,"Neoplazii — SK visceral versus cutanat și NHL/EBV",
 "Gradientul prognostic visceral față de cutanat, profilul NHL extraganglionar EBV și citologia cervicală anuală.",
 ["SK cu afectare viscerală (ganglioni, plămâni, tract GI) are prognostic mai rezervat decât cel limitat la tegument.","Limfoamele sunt frecvent NHL cu celulă mare B, extraganglionare (creier, plămân, GI), adesea asociate EBV.","Citologia cervicală anuală se recomandă femeilor cu HIV pentru modificările pre-neoplazice HPV.","Nu: forma viscerală are prognostic mai rezervat decât cea cutanată.","Nu: limfoamele sunt agresive, adesea cu simptome B și asociate EBV."]],
 [8,"Inversează prognosticul SK visceral/cutanat și face limfomul indolent, două neoplazii de pe aceeași deschidere."],["prognostic mai rezervat","citologiei cervicale"]),
];
